import { getChordTypeDefinition } from '../data/chordTypes';
import { assignFingering, type BarreAssignment, type FingeringAssignment } from './FingeringEngine';
import { AVAILABLE_TENSIONS, validateTensions, type TensionId } from './TensionEngine';
import { parseChord } from '../utils/chordMath';

const NOTE_NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const INTERVAL_NAMES = ['R', 'b2', '2', 'b3', '3', '4', 'b5', '5', 'b6', '6', 'b7', '7'];
const OPEN_STRING_MIDI = [40, 45, 50, 55, 59, 64];
const STRING_GROUPS = [
  { id: '6-5-4-3-2-1', strings: [0, 1, 2, 3, 4, 5] },
  { id: '5-4-3-2', strings: [1, 2, 3, 4] },
  { id: '6-4-3-2', strings: [0, 2, 3, 4] },
  { id: '5-3-2-1', strings: [1, 3, 4, 5] },
  { id: '4-3-2-1', strings: [2, 3, 4, 5] },
  { id: '6-3-2-1', strings: [0, 3, 4, 5] },
] as const;
const POSITIONS = [0, 3, 5, 7, 9, 12];

export type VoicingFamily = 'inversion' | 'close' | 'drop';
export type VoicingType = 'inversion' | 'close' | 'drop-2' | 'drop-3' | 'drop-2&4' | 'drop-2&3';

export interface VoicingNote {
  string: number;
  fret: number;
  midi: number;
  pitchClass: string;
  interval: number;
  intervalLabel: string;
}

export interface GeneratedVoicing {
  id: string;
  label: string;
  family: VoicingFamily;
  type: VoicingType;
  stringGroup: string;
  position: number;
  frets: (number | null)[];
  notes: VoicingNote[];
  bassNote: string;
  inversion: number;
  minFret: number;
  maxFret: number;
  fretSpan: number;
  barres: BarreAssignment[];
  fingering: FingeringAssignment;
  maxMovement?: number;
}

export interface VoicingGeneratorOptions {
  stringGroup?: string;
  position?: number;
  maxFretSpan?: number;
  tensions?: readonly TensionId[];
}

interface PitchPattern {
  label: string;
  family: VoicingFamily;
  type: VoicingType;
  inversion: number;
  pitches: number[];
  bassPitchClass: number;
}

interface Candidate {
  voicing: GeneratedVoicing;
  score: number;
}

const cache = new Map<string, GeneratedVoicing[]>();

function combinations(values: readonly number[], count: number): number[][] {
  if (count === 0) return [[]];
  if (values.length < count) return [];
  const result: number[][] = [];
  const visit = (start: number, picked: number[]) => {
    if (picked.length === count) {
      result.push([...picked]);
      return;
    }
    for (let index = start; index < values.length; index++) {
      picked.push(values[index]);
      visit(index + 1, picked);
      picked.pop();
    }
  };
  visit(0, []);
  return result;
}

function createPatterns(root: number, intervals: readonly number[]): PitchPattern[] {
  const seenPitchClasses = new Set<number>();
  const uniqueIntervals = intervals.filter(interval => {
    const pitchClass = ((interval % 12) + 12) % 12;
    if (seenPitchClasses.has(pitchClass)) return false;
    seenPitchClasses.add(pitchClass);
    return true;
  });
  const rootMidi = 48 + root;
  const closePitches = uniqueIntervals.map(interval => rootMidi + interval);
  const patterns: PitchPattern[] = [];

  for (let inversion = 0; inversion < closePitches.length; inversion++) {
    const pitches = [
      ...closePitches.slice(inversion),
      ...closePitches.slice(0, inversion).map(pitch => pitch + 12),
    ].sort((left, right) => left - right);
    patterns.push({
      label: `Inversion ${inversion}`,
      family: 'inversion',
      type: 'inversion',
      inversion,
      pitches,
      bassPitchClass: (root + uniqueIntervals[inversion]) % 12,
    });

    if (inversion === 0) {
      patterns.push({ label: 'Close', family: 'close', type: 'close', inversion, pitches, bassPitchClass: root });
    }

    const drop = (name: VoicingType, droppedVoices: number[]) => {
      if (closePitches.length < Math.max(...droppedVoices) + 1) return;
      const dropped = pitches.map((pitch, index) =>
        droppedVoices.includes(pitches.length - 1 - index) ? pitch - 12 : pitch,
      ).sort((left, right) => left - right);
      patterns.push({
        label: name === 'drop-2' ? 'Drop-2' : name === 'drop-3' ? 'Drop-3' : name === 'drop-2&4' ? 'Drop-2&4' : 'Drop-2&3',
        family: 'drop',
        type: name,
        inversion,
        pitches: dropped,
        bassPitchClass: dropped[0] % 12,
      });
    };

    drop('drop-2', [1]);
    drop('drop-3', [2]);
    drop('drop-2&4', [1, 3]);
    drop('drop-2&3', [1, 2]);
  }

  if (uniqueIntervals.length > 4) {
    for (const voiceCount of [4, 3]) {
      combinations(uniqueIntervals.map((_, index) => index), voiceCount)
        .filter(indices => indices.includes(0))
        .forEach(indices => {
          const shell = indices.map(index => closePitches[index]);
          for (let inversion = 0; inversion < shell.length; inversion++) {
            const pitches = [
              ...shell.slice(inversion),
              ...shell.slice(0, inversion).map(pitch => pitch + 12),
            ].sort((left, right) => left - right);
            patterns.push({
              label: `Shell ${voiceCount} · ${inversion}`,
              family: 'close',
              type: 'close',
              inversion,
              pitches,
              bassPitchClass: pitches[0] % 12,
            });
          }
        });
    }
  }

  return patterns;
}

function buildVoicing(
  chordRoot: number,
  pattern: PitchPattern,
  groupId: string,
  position: number,
  frets: (number | null)[],
  maxFretSpan: number,
): GeneratedVoicing | null {
  const notes = frets.flatMap((fret, string) => {
    if (fret === null) return [];
    const midi = OPEN_STRING_MIDI[string] + fret;
    return [{
      string,
      fret,
      midi,
      pitchClass: NOTE_NAMES[midi % 12],
      interval: (midi % 12 - chordRoot + 12) % 12,
      intervalLabel: INTERVAL_NAMES[(midi % 12 - chordRoot + 12) % 12],
    }];
  });
  if (notes.length > 6 || notes.length < pattern.pitches.length) return null;

  const presentPitchClasses = new Set(notes.map(note => note.midi % 12));
  if (pattern.pitches.some(pitch => !presentPitchClasses.has(pitch % 12))) return null;
  const bass = notes.reduce((lowest, note) => note.midi < lowest.midi ? note : lowest);
  if (bass.midi % 12 !== pattern.bassPitchClass) return null;

  const playedFrets = notes.filter(note => note.fret > 0).map(note => note.fret);
  const minFret = playedFrets.length > 0 ? Math.min(...playedFrets) : 0;
  const maxFret = playedFrets.length > 0 ? Math.max(...playedFrets) : 0;
  const fretSpan = maxFret - minFret;
  if (fretSpan > maxFretSpan) return null;

  const fingering = assignFingering(frets);
  if (!fingering.playable) return null;
  const barres = fingering.barre ? [fingering.barre] : [];
  if (barres.length > 1) return null;

  const fretSignature = frets.map(fret => fret === null ? 'x' : fret).join('-');
  const label = pattern.family === 'inversion'
    ? `${pattern.label} · ${groupId}`
    : `${pattern.label} · ${groupId}`;
  return {
    id: `${pattern.type}:${groupId}:${fretSignature}`,
    label,
    family: pattern.family,
    type: pattern.type,
    stringGroup: groupId,
    position,
    frets,
    notes,
    bassNote: NOTE_NAMES[bass.midi % 12],
    inversion: pattern.inversion,
    minFret,
    maxFret,
    fretSpan,
    barres,
    fingering,
  };
}

function findPatternCandidates(
  chordRoot: number,
  pattern: PitchPattern,
  options: VoicingGeneratorOptions,
): Candidate[] {
  const maxFretSpan = options.maxFretSpan ?? 5;
  const positions = options.position === undefined ? POSITIONS : [options.position];
  const groups = STRING_GROUPS.filter(group => !options.stringGroup || group.id === options.stringGroup);
  const candidates: Candidate[] = [];
  const seen = new Set<string>();

  for (const group of groups) {
    const stringSubsets = combinations(group.strings, pattern.pitches.length);
    for (const position of positions) {
      for (const subset of stringSubsets) {
        const fretOptions = pattern.pitches.map((pitch, voice) => {
          const string = subset[voice];
          const openMidi = OPEN_STRING_MIDI[string];
          const pitchClass = pitch % 12;
          const min = position === 0 ? 0 : position;
          const max = position === 0 ? 4 : position + 4;
          const frets: number[] = [];
          for (let fret = min; fret <= max; fret++) {
            if ((openMidi + fret) % 12 === pitchClass) frets.push(fret);
          }
          if (position !== 0 && openMidi % 12 === pitchClass) frets.push(0);
          return frets;
        });
        if (fretOptions.some(frets => frets.length === 0)) continue;

        const selected = Array<number>(subset.length).fill(0);
        const visit = (voice: number) => {
          if (voice === subset.length) {
            const frets: (number | null)[] = Array<number | null>(6).fill(null);
            subset.forEach((string, index) => { frets[string] = selected[index]; });
            const voicing = buildVoicing(chordRoot, pattern, group.id, position, frets, maxFretSpan);
            if (!voicing || seen.has(voicing.id)) return;
            seen.add(voicing.id);
            const score = voicing.fretSpan * 100
              + voicing.maxFret * 2
              + voicing.fingering.mutedStrings.length
              + Math.max(0, voicing.notes.length - pattern.pitches.length) * 4;
            candidates.push({ voicing, score });
            return;
          }
          fretOptions[voice].forEach(fret => {
            selected[voice] = fret;
            visit(voice + 1);
          });
        };
        visit(0);
      }
    }
  }

  return candidates.sort((left, right) => left.score - right.score);
}

function normalizeChordName(input: string | { root: string; type: string }): string {
  if (typeof input === 'string') return input;
  const rootChord = parseChord(input.root);
  if (rootChord && rootChord.quality) return input.root;
  const type = getChordTypeDefinition(input.type);
  if (!type) throw new RangeError(`Unsupported chord type: ${input.type}`);
  return `${input.root}${type.suffix}`;
}

export function generateVoicings(
  chordInput: string | { root: string; type: string },
  options: VoicingGeneratorOptions = {},
): GeneratedVoicing[] {
  const chordName = normalizeChordName(chordInput);
  const chord = parseChord(chordName);
  if (!chord) throw new RangeError(`Unsupported chord: ${chordName}`);
  const chordType = getChordTypeDefinition(chord.quality || 'major');
  if (!chordType) throw new RangeError(`Unsupported chord type: ${chord.quality || 'major'}`);

  const tensionValidation = validateTensions(chord.quality || 'major', options.tensions ?? []);
  const intervals = [...chord.intervals];
  tensionValidation.allowed.forEach(tension => {
    const interval = AVAILABLE_TENSIONS.find(item => item.id === tension)?.interval;
    if (interval !== undefined && intervals.length < 6) intervals.push(interval);
  });
  const cacheKey = [
    chordName,
    options.stringGroup ?? 'all',
    options.position ?? 'all',
    options.maxFretSpan ?? 5,
    [...(options.tensions ?? [])].sort().join(','),
  ].join('|');
  const cached = cache.get(cacheKey);
  if (cached) return cached.map(voicing => ({ ...voicing, frets: [...voicing.frets], notes: [...voicing.notes] }));

  const patterns = createPatterns(chord.root, intervals);
  const selected: GeneratedVoicing[] = [];
  const selectedIds = new Set<string>();
  const bestInversions = new Map<number, Candidate>();
  const dropGroups = new Map<string, Candidate>();

  patterns.forEach(pattern => {
    const candidates = findPatternCandidates(chord.root, pattern, options);
    if (pattern.type === 'inversion') {
      const best = candidates[0];
      const current = bestInversions.get(pattern.inversion);
      if (best && (!current || best.score < current.score)) bestInversions.set(pattern.inversion, best);
      return;
    }
    if (pattern.family !== 'drop') {
      candidates.slice(0, 2).forEach(candidate => {
        if (selectedIds.has(candidate.voicing.id)) return;
        selectedIds.add(candidate.voicing.id);
        selected.push(candidate.voicing);
      });
      return;
    }

    candidates.forEach(candidate => {
      const key = `${pattern.type}:${candidate.voicing.stringGroup}`;
      const current = dropGroups.get(key);
      if (!current || candidate.score < current.score) dropGroups.set(key, candidate);
    });
  });

  [...bestInversions.entries()]
    .sort(([left], [right]) => left - right)
    .forEach(([, candidate]) => {
      if (selectedIds.has(candidate.voicing.id)) return;
      selectedIds.add(candidate.voicing.id);
      selected.unshift(candidate.voicing);
    });

  [...dropGroups.values()]
    .sort((left, right) => left.score - right.score)
    .forEach(candidate => {
      if (selectedIds.has(candidate.voicing.id)) return;
      selectedIds.add(candidate.voicing.id);
      selected.push(candidate.voicing);
    });

  const result = selected.slice(0, 32);
  cache.set(cacheKey, result);
  return result.map(voicing => ({ ...voicing, frets: [...voicing.frets], notes: [...voicing.notes] }));
}
