import type { ChordDefinition } from './chordLibrary';

export type ChordTypeFamily =
  | 'triad'
  | 'seventh'
  | 'extended'
  | 'add'
  | 'suspended'
  | 'special'
  | 'legacy';

export interface ChordTypeDefinition {
  id: string;
  suffix: string;
  label: string;
  family: ChordTypeFamily;
  intervals: number[];
  quality: ChordDefinition['quality'];
  difficulty: 1 | 2 | 3 | 4 | 5;
  commonUse: string;
  recommendedScales: string[];
  aliases?: string[];
  canonical?: boolean;
}

const canonicalType = (
  id: string,
  suffix: string,
  label: string,
  family: Exclude<ChordTypeFamily, 'legacy'>,
  intervals: number[],
  quality: ChordDefinition['quality'],
  difficulty: ChordTypeDefinition['difficulty'],
  commonUse: string,
  recommendedScales: string[],
  aliases?: string[],
): ChordTypeDefinition => ({
  id, suffix, label, family, intervals, quality, difficulty, commonUse,
  recommendedScales, aliases, canonical: true,
});

const legacyType = (
  id: string,
  suffix: string,
  label: string,
  intervals: number[],
  quality: ChordDefinition['quality'],
): ChordTypeDefinition => ({
  id,
  suffix,
  label,
  family: 'legacy',
  intervals,
  quality,
  difficulty: 3,
  commonUse: 'Existing FretLab chord type',
  recommendedScales: [],
});

