export const CANONICAL_CHORD_TYPES = CHORD_TYPES.filter(type => type.canonical);

export function getChordTypeDefinition(typeOrSuffix: string): ChordTypeDefinition | undefined {
  const normalized = typeOrSuffix.toLowerCase();
  return CHORD_TYPES.find(type =>
    type.id.toLowerCase() === normalized ||
    type.suffix.toLowerCase() === normalized ||
    type.aliases?.some(alias => alias.toLowerCase() === normalized),
  );
}
