import { getChordTypeDefinition } from '../data/chordTypes';

export const AVAILABLE_TENSIONS = [
  { id: 'b9', label: 'b9', interval: 13 },
  { id: '9', label: '9', interval: 14 },
  { id: '#9', label: '#9', interval: 15 },
  { id: '11', label: '11', interval: 17 },
  { id: '#11', label: '#11', interval: 18 },
  { id: 'b13', label: 'b13', interval: 20 },
  { id: '13', label: '13', interval: 21 },
] as const;

export type TensionId = typeof AVAILABLE_TENSIONS[number]['id'];

export interface TensionValidation {
  allowed: TensionId[];
  conflicts: string[];
}

export function validateTensions(chordType: string, requested: readonly string[]): TensionValidation {
  const suffix = chordType.match(/^[A-G](?:#|b)?(.*)$/i)?.[1];
  const definition = getChordTypeDefinition(chordType)
    ?? getChordTypeDefinition(suffix || chordType || 'major');
  if (!definition) throw new RangeError(`Unsupported chord type: ${chordType}`);

  const baseIntervals = new Set(definition.intervals.map(interval => interval % 12));
  const selected = new Set(requested);
  const conflicts: string[] = [];

  if (selected.has('11') && baseIntervals.has(4)) {
    conflicts.push('11 conflicts with the chord third.');
  }
  if (definition.quality === 'dominant' && selected.has('13') && baseIntervals.has(10)) {
    conflicts.push('13 conflicts with the dominant seventh.');
  }
  if (selected.has('9') && (selected.has('b9') || selected.has('#9'))) {
    conflicts.push('Natural 9 cannot be combined with b9 or #9.');
  }
  if (selected.has('b9') && selected.has('#9')) {
    conflicts.push('b9 and #9 cannot be used together.');
  }

  const allowed = AVAILABLE_TENSIONS
    .map(tension => tension.id)
    .filter((tension): tension is TensionId => selected.has(tension))
    .filter(tension => {
      if (tension === '11' && baseIntervals.has(4)) return false;
      if (tension === '13' && definition.quality === 'dominant' && baseIntervals.has(10)) return false;
      if (tension === '9' && (selected.has('b9') || selected.has('#9'))) return false;
      if (tension === 'b9' && selected.has('#9')) return false;
      if (tension === '#9' && selected.has('b9')) return false;
      return true;
    });

  return { allowed, conflicts };
}
