export interface BarreAssignment {
  fret: number;
  strings: number[];
}

export interface FingeringAssignment {
  fingers: number[];
  barre?: BarreAssignment;
  mutedStrings: number[];
  playable: boolean;
}

export function assignFingering(frets: readonly (number | null | 'x')[]): FingeringAssignment {
  const fingers = Array<number>(frets.length).fill(0);
  const mutedStrings = frets.flatMap((fret, string) => fret === null || fret === 'x' ? [string] : []);
  const fretGroups = new Map<number, number[]>();

  frets.forEach((fret, string) => {
    if (typeof fret !== 'number' || fret === 0) return;
    const strings = fretGroups.get(fret) ?? [];
    strings.push(string);
    fretGroups.set(fret, strings);
  });

  const runs = [...fretGroups.entries()].flatMap(([fret, strings]) => {
    const fretRuns: number[][] = [];
    strings.forEach(string => {
      const current = fretRuns[fretRuns.length - 1];
      if (current && current[current.length - 1] === string - 1) current.push(string);
      else fretRuns.push([string]);
    });
    return fretRuns.map(run => ({ fret, strings: run }));
  });
  const barre = runs
    .filter(run => run.strings.length >= 2)
    .sort((left, right) => right.strings.length - left.strings.length)[0];

  let nextFinger = 1;
  let playable = true;
  const assignedBarre = new Set(barre?.strings ?? []);
  if (barre) {
    barre.strings.forEach(string => { fingers[string] = 1; });
    nextFinger = 2;
  }

  runs.forEach(run => {
    const remainingStrings = run.strings.filter(string => !assignedBarre.has(string));
    remainingStrings.forEach(string => {
      if (nextFinger > 4) {
        playable = false;
        return;
      }
      fingers[string] = nextFinger;
      nextFinger++;
    });
  });

  return {
    fingers,
    barre: barre ? { fret: barre.fret, strings: barre.strings } : undefined,
    mutedStrings,
    playable,
  };
}
