import type { GeneratedVoicing } from './VoicingGenerator';

function notesOf(voicing: GeneratedVoicing): number[] {
  return voicing.notes.map(note => note.midi).sort((left, right) => left - right);
}

export function getVoiceLeadingDistance(from: GeneratedVoicing, to: GeneratedVoicing): number {
  const source = notesOf(from);
  const target = notesOf(to);
  if (source.length === 0 || target.length === 0) return Infinity;

  const used = new Set<number>();
  const movement = source.reduce((total, pitch) => {
    let bestIndex = -1;
    let bestDistance = Infinity;
    target.forEach((candidate, index) => {
      if (used.has(index)) return;
      const distance = Math.min(
        Math.abs(candidate - pitch),
        Math.abs(candidate - pitch - 12),
        Math.abs(candidate - pitch + 12),
      );
      if (distance < bestDistance) {
        bestDistance = distance;
        bestIndex = index;
      }
    });
    if (bestIndex === -1) return total + 12;
    used.add(bestIndex);
    return total + bestDistance;
  }, 0);

  return movement + Math.abs(source.length - target.length) * 12;
}

export function orderVoicingsByVoiceLeading(
  voicings: readonly GeneratedVoicing[],
  start?: GeneratedVoicing,
): GeneratedVoicing[] {
  const remaining = [...voicings];
  const ordered: GeneratedVoicing[] = [];
  let previous = start;

  while (remaining.length > 0) {
    let bestIndex = 0;
    let bestMovement = previous ? getVoiceLeadingDistance(previous, remaining[0]) : 0;
    for (let index = 1; index < remaining.length; index++) {
      const movement = previous ? getVoiceLeadingDistance(previous, remaining[index]) : 0;
      if (movement < bestMovement) {
        bestIndex = index;
        bestMovement = movement;
      }
    }

    const [next] = remaining.splice(bestIndex, 1);
    const orderedVoicing = { ...next, maxMovement: previous ? bestMovement : undefined };
    ordered.push(orderedVoicing);
    previous = orderedVoicing;
  }

  return ordered;
}
