import React, { useState, useEffect, useRef, useMemo } from 'react';
import { CHORD_DB, generateFallbackVoicing, type Voicing } from '../../services/ChordDatabase';
import { useTranslation } from '../../context/LocaleContext';
import { playPluckedGuitarChord } from '../../utils/pluckedGuitarChord';
import { CHORD_TYPES, getChordTypeDefinition } from '../../data/chordTypes';
import { AVAILABLE_TENSIONS, validateTensions, type TensionId } from '../../engines/TensionEngine';
import { generateVoicings } from '../../engines/VoicingGenerator';
import { orderVoicingsByVoiceLeading } from '../../engines/VoiceLeadingEngine';

const ROOTS = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

const CHORD_CATEGORIES = {
  'Major': [
    { suffix: '', label: 'Major (Triad)' },
    { suffix: 'maj7', label: 'maj7 (Major 7th)' },
    { suffix: 'maj9', label: 'maj9 (Major 9th)' },
    { suffix: 'maj11', label: 'maj11 (Major 11th)' },
    { suffix: 'maj9#11', label: 'maj9(#11) (Lydian)' },
    { suffix: 'maj7b9', label: 'maj7(b9)' }
  ],
  'Minor': [
    { suffix: 'm', label: 'Minor (Triad)' },
    { suffix: 'm7', label: 'm7 (Minor 7th)' },
    { suffix: 'm9', label: 'm9 (Minor 9th)' },
    { suffix: 'm11', label: 'm11 (Minor 11th)' },
    { suffix: 'm7b9', label: 'm7(b9)' }
  ],
  'Dominant': [
    { suffix: '7', label: '7 (Dominant 7th)' },
    { suffix: '9', label: '9 (Dominant 9th)' },
    { suffix: '11', label: '11 (Dominant 11th)' },
    { suffix: '7b9', label: '7b9 (Dominant b9)' },
    { suffix: '7#9', label: '7#9 (Hendrix Chord)' }
  ],
  'Diminished / Alt': [
    { suffix: 'm7b5', label: 'm7b5 (Half-Diminished)' },
    { suffix: 'm9b5', label: 'm9b5 (Locrian 9th)' },
    { suffix: 'm7b5b9', label: 'm7b5(b9)' },
    { suffix: 'm11b5', label: 'm11b5' },
    { suffix: 'dim7', label: 'dim7 (Full-Diminished)' },
    { suffix: 'dim', label: 'dim (Diminished Triad)' }
  ]
};

const STRINGS = ['E', 'A', 'D', 'G', 'B', 'e'];

// 🔥 ПРИНИМАЕМ КОМАНДУ ОТ ИИ ЧЕРЕЗ PROPS
interface Props {
  targetChord?: string | null;
}

const ChordDictionary: React.FC<Props> = ({ targetChord }) => {
  const { t } = useTranslation();
  const [selectedRoot, setSelectedRoot] = useState('C');
  const [selectedSuffix, setSelectedSuffix] = useState('');
  const [activeCategory, setActiveCategory] = useState<keyof typeof CHORD_CATEGORIES>('Major');
  const [explorerType, setExplorerType] = useState('major');
  const [explorerFamily, setExplorerFamily] = useState('all');
  const [explorerGroup, setExplorerGroup] = useState('all');
  const [explorerPosition, setExplorerPosition] = useState('all');
  const [selectedTensions, setSelectedTensions] = useState<TensionId[]>([]);
  const [referenceVoicingId, setReferenceVoicingId] = useState('');
  const [tensionWarning, setTensionWarning] = useState('');

  // 🔥 НОВОЕ: раньше компонент вообще не знал о ширине экрана — три колонки
  // по 260px/300px/flex стояли жёстко всегда, поэтому на мобильном третья
  // колонка (диаграмма аккорда) просто обрезалась за край экрана.
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // ⚠️ FIX: раньше playChordAudio создавал новый AudioContext на КАЖДЫЙ клик
  // по аккорду и никогда его не закрывал. Это словарь аккордов — по нему
  // кликают десятками за сессию, так что за пару минут накапливались десятки
  // не закрытых AudioContext (тяжёлый нативный ресурс, отдельный аудио-поток).
  // Теперь держим один общий контекст на весь компонент и закрываем при unmount.
  const audioCtxRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    return () => {
      if (audioCtxRef.current) {
        audioCtxRef.current.close();
        audioCtxRef.current = null;
      }
    };
  }, []);

  const currentChordName = `${selectedRoot}${selectedSuffix}`;
  const explorerChordType = getChordTypeDefinition(explorerType) ?? CHORD_TYPES[0];
  const explorerChordName = `${selectedRoot}${explorerChordType.suffix}`;
  const generatedVoicings = useMemo(() => generateVoicings(explorerChordName, {
    stringGroup: explorerGroup === 'all' ? undefined : explorerGroup,
    position: explorerPosition === 'all' ? undefined : Number(explorerPosition),
    tensions: selectedTensions,
  }), [explorerChordName, explorerGroup, explorerPosition, selectedTensions]);
  const filteredVoicings = useMemo(() => generatedVoicings.filter(voicing =>
    explorerFamily === 'all' || voicing.family === explorerFamily,
  ), [generatedVoicings, explorerFamily]);
  const referenceVoicing = generatedVoicings.find(voicing => voicing.id === referenceVoicingId);
  const orderedVoicings = useMemo(
    () => orderVoicingsByVoiceLeading(filteredVoicings, referenceVoicing),
    [filteredVoicings, referenceVoicing],
  );

  // 🔥 СЛУШАЕМ ИИ: Если пришла команда показать аккорд, парсим его и настраиваем интерфейс
  useEffect(() => {
    if (targetChord) {
      // Разбиваем аккорд (например, F#m7b5) на корень (F#) и суффикс (m7b5)
      const match = targetChord.match(/^([A-G]#?)(.*)$/);
      if (match) {
        const root = match[1];
        const suffix = match[2] || '';
        
        setSelectedRoot(root);
        setSelectedSuffix(suffix);
        
        // Ищем категорию, в которой лежит этот суффикс, чтобы открыть нужную вкладку
        for (const [catName, chords] of Object.entries(CHORD_CATEGORIES)) {
          if (chords.some(c => c.suffix === suffix)) {
            setActiveCategory(catName as any);
            break;
          }
        }
      }
    }
  }, [targetChord]);

  useEffect(() => {
    setExplorerType(getChordTypeDefinition(selectedSuffix)?.id ?? 'major');
    setSelectedTensions([]);
    setTensionWarning('');
    setReferenceVoicingId('');
  }, [selectedSuffix]);

  const getVoicings = (): Voicing[] => {
    if (CHORD_DB[currentChordName]) return CHORD_DB[currentChordName];
    return generateFallbackVoicing(currentChordName);
  };

  const voicings = getVoicings();

  const playChordAudio = (frets: (number | 'x' | null)[]) => {
    try {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioContextClass) return;

      // Переиспользуем один контекст вместо создания нового при каждом клике
      if (!audioCtxRef.current) {
        audioCtxRef.current = new AudioContextClass();
      }
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();

      const OPEN_FREQS = [82.41, 110.00, 146.83, 196.00, 246.94, 329.63];
      const frequencies: number[] = [];
      for (let i = 0; i < 6; i++) {
        const fret = frets[i];
        if (fret === 'x' || fret === null) continue;
        frequencies.push(OPEN_FREQS[i] * Math.pow(2, Number(fret) / 12));
      }
      playPluckedGuitarChord({
        context: ctx,
        frequencies,
        startTime: ctx.currentTime,
        duration: 1,
        velocity: 0.2,
        strumDelay: 0.05,
        connect: gain => gain.connect(ctx.destination),
      });
    } catch (e) {
      console.error("Audio Synthesis Failed:", e);
    }
  };

  return (
    <div style={{ background: 'var(--bg-panel)', borderRadius: 'var(--radius)', border: '1px solid var(--border-color)', height: '100%', display: 'flex', flexDirection: 'column', overflow: 'hidden', boxShadow: '0 8px 32px rgba(0,0,0,0.3)' }}>
      <div style={{ padding: isMobile ? '14px 16px' : '18px 24px', background: 'var(--bg-primary)', borderBottom: '1px solid var(--border-color)', display: 'flex', alignItems: 'center', gap: '12px' }}>
        <span style={{ fontSize: '20px' }}>📖</span>
        <div style={{ display: 'flex', flexDirection: 'column' }}>
<span style={{ fontSize: '14px', fontWeight: 800, color: 'var(--text-primary)' }}>{t.chordDictionary.interactive}</span>
          <span style={{ fontSize: '11px', color: 'var(--text-muted)', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.5px' }}>{t.chordDictionary.explore}</span>
        </div>
      </div>

      {/* 🔥 ИЗМЕНЕНО: flexDirection зависит от isMobile — на мобильном колонки
          складываются в вертикальный поток вместо трёх параллельных рядов.
          overflowY тоже переезжает сюда на мобильном, чтобы можно было
          скроллить всю цепочку шагов целиком. */}
      <div style={{ display: 'flex', flexDirection: isMobile ? 'column' : 'row', flex: 1, overflow: 'hidden', overflowY: isMobile ? 'auto' : 'hidden' }} className="dictionary-layout">
        <div style={{ width: isMobile ? '100%' : '260px', borderRight: isMobile ? 'none' : '1px solid var(--border-color)', borderBottom: isMobile ? '1px solid var(--border-color)' : 'none', background: 'var(--bg-primary)', padding: isMobile ? '16px' : '20px', display: 'flex', flexDirection: 'column', gap: '16px', overflowY: isMobile ? 'visible' : 'auto', flexShrink: 0 }}>
          <div>
<div style={{ fontSize: '12px', color: 'var(--text-muted)', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: '10px' }}>{t.chordDictionary.selectRoot}</div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '6px' }}>
              {ROOTS.map(root => (
                <button
                  key={root}
                  onClick={() => setSelectedRoot(root)}
                  style={{ background: selectedRoot === root ? 'var(--accent)' : 'var(--bg-secondary)', color: selectedRoot === root ? 'var(--text-on-accent)' : 'var(--text-primary)', border: '1px solid var(--border-color)', padding: '8px 0', minHeight: '44px', borderRadius: '8px', fontWeight: 800, fontSize: '14px', cursor: 'pointer', transition: '0.15s' }}
                >
                  {root}
                </button>
              ))}

              <section style={{ width: '100%', maxWidth: '1040px', margin: '12px auto 28px', padding: isMobile ? '18px 14px' : '24px', background: 'var(--bg-panel)', border: '1px solid var(--border-color)', borderRadius: '16px', display: 'flex', flexDirection: 'column', gap: '18px' }}>
                <div>
                  <h3 style={{ margin: 0, color: 'var(--text-primary)', fontSize: '22px' }}>{t.chordExplorer.title}</h3>
                  <div style={{ color: 'var(--text-secondary)', marginTop: '5px' }}>{explorerChordName}</div>
                </div>

                <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr 1fr' : 'repeat(4, minmax(140px, 1fr))', gap: '12px' }}>
                  <label style={{ display: 'grid', gap: '6px', color: 'var(--text-secondary)', fontSize: '13px' }}>
                    {t.chordExplorer.selectType}
                    <select value={explorerType} onChange={event => {
                      setExplorerType(event.target.value);
                      setSelectedTensions([]);
                      setTensionWarning('');
                      setReferenceVoicingId('');
                    }} style={{ minHeight: '44px', background: 'var(--bg-primary)', color: 'var(--text-primary)', border: '1px solid var(--border-color)', borderRadius: '8px', padding: '0 10px' }}>
                      {CHORD_TYPES.map(type => <option key={type.id} value={type.id}>{type.label} ({type.suffix || 'maj'})</option>)}
                    </select>
                  </label>

                  <label style={{ display: 'grid', gap: '6px', color: 'var(--text-secondary)', fontSize: '13px' }}>
                    {t.chordExplorer.family}
                    <select value={explorerFamily} onChange={event => setExplorerFamily(event.target.value)} style={{ minHeight: '44px', background: 'var(--bg-primary)', color: 'var(--text-primary)', border: '1px solid var(--border-color)', borderRadius: '8px', padding: '0 10px' }}>
                      <option value="all">{t.chordExplorer.all}</option>
                      <option value="inversion">{t.chordExplorer.inversions}</option>
                      <option value="close">{t.chordExplorer.close}</option>
                      <option value="drop">{t.chordExplorer.drops}</option>
                    </select>
                  </label>

                  <label style={{ display: 'grid', gap: '6px', color: 'var(--text-secondary)', fontSize: '13px' }}>
                    {t.chordExplorer.group}
                    <select value={explorerGroup} onChange={event => setExplorerGroup(event.target.value)} style={{ minHeight: '44px', background: 'var(--bg-primary)', color: 'var(--text-primary)', border: '1px solid var(--border-color)', borderRadius: '8px', padding: '0 10px' }}>
                      <option value="all">{t.chordExplorer.allStrings}</option>
                      {['6-5-4-3-2-1', '5-4-3-2', '6-4-3-2', '5-3-2-1', '4-3-2-1', '6-3-2-1'].map(group => <option key={group} value={group}>{group}</option>)}
                    </select>
                  </label>

                  <label style={{ display: 'grid', gap: '6px', color: 'var(--text-secondary)', fontSize: '13px' }}>
                    {t.chordExplorer.position}
                    <select value={explorerPosition} onChange={event => setExplorerPosition(event.target.value)} style={{ minHeight: '44px', background: 'var(--bg-primary)', color: 'var(--text-primary)', border: '1px solid var(--border-color)', borderRadius: '8px', padding: '0 10px' }}>
                      <option value="all">{t.chordExplorer.allPositions}</option>
                      {[0, 3, 5, 7, 9, 12].map(position => <option key={position} value={position}>{position === 0 ? t.chordExplorer.open : `${position}fr`}</option>)}
                    </select>
                  </label>
                </div>

                <div>
                  <div style={{ color: 'var(--text-secondary)', fontSize: '13px', marginBottom: '8px' }}>{t.chordExplorer.tensions}</div>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
                    {AVAILABLE_TENSIONS.map(tension => {
                      const active = selectedTensions.includes(tension.id);
                      return (
                        <button key={tension.id} type="button" aria-pressed={active} onClick={() => {
                          const requested = active
                            ? selectedTensions.filter(item => item !== tension.id)
                            : [...selectedTensions, tension.id];
                          const validation = validateTensions(explorerChordType.suffix || 'major', requested);
                          if (validation.conflicts.length > 0) {
                            setTensionWarning(validation.conflicts[0]);
                            return;
                          }
                          setTensionWarning('');
                          setSelectedTensions(requested);
                        }} style={{ minWidth: '44px', minHeight: '40px', padding: '0 12px', borderRadius: '20px', border: `1px solid ${active ? 'var(--accent)' : 'var(--border-color)'}`, background: active ? 'var(--accent)' : 'var(--bg-primary)', color: active ? 'var(--text-on-accent)' : 'var(--text-primary)', cursor: 'pointer' }}>
                          {tension.label}
                        </button>
                      );
                    })}
                  </div>
                  {tensionWarning && <div role="status" style={{ color: 'var(--accent)', fontSize: '13px', marginTop: '8px' }}>{tensionWarning}</div>}
                </div>

                <label style={{ display: 'flex', alignItems: 'center', gap: '10px', maxWidth: '480px', color: 'var(--text-secondary)', fontSize: '13px' }}>
                  {t.chordExplorer.compareFrom}
                  <select value={referenceVoicingId} onChange={event => setReferenceVoicingId(event.target.value)} style={{ flex: 1, minHeight: '44px', background: 'var(--bg-primary)', color: 'var(--text-primary)', border: '1px solid var(--border-color)', borderRadius: '8px', padding: '0 10px' }}>
                    <option value="">{t.chordExplorer.all}</option>
                    {generatedVoicings.map(voicing => <option key={voicing.id} value={voicing.id}>{voicing.label} ({voicing.frets.map(fret => fret === null ? 'x' : fret).join('-')})</option>)}
                  </select>
                </label>

                {orderedVoicings.length === 0 ? (
                  <div style={{ color: 'var(--text-secondary)', padding: '16px 0' }}>{t.chordExplorer.noResults}</div>
                ) : (
                  <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : 'repeat(auto-fit, minmax(260px, 1fr))', gap: '14px' }}>
                    {orderedVoicings.map(voicing => {
                      const diagramBase = voicing.minFret > 0 ? voicing.minFret : 1;
                      const voicingLabel = voicing.family === 'inversion'
                        ? `${t.chordExplorer.inversions} ${voicing.inversion}`
                        : voicing.type === 'close' ? t.chordExplorer.close : voicing.type.replace('-', ' ');
                      return (
                        <article key={voicing.id} style={{ background: 'var(--bg-primary)', border: '1px solid var(--border-color)', borderRadius: '12px', padding: '16px', display: 'flex', flexDirection: 'column', gap: '12px' }}>
                          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '8px' }}>
                            <strong style={{ color: 'var(--text-primary)' }}>{voicingLabel}</strong>
                            <button type="button" onClick={() => playChordAudio(voicing.frets)} style={{ minHeight: '40px', padding: '0 12px', borderRadius: '20px', border: '1px solid var(--accent)', background: 'var(--bg-secondary)', color: 'var(--accent)', cursor: 'pointer' }}>{t.chordExplorer.play}</button>
                          </div>
                          <div style={{ display: 'flex', justifyContent: 'center', padding: '8px 0', background: 'var(--bg-secondary)', borderRadius: '8px' }}>
                            <svg viewBox="0 0 240 270" role="img" aria-label={`${explorerChordName} ${voicingLabel}`} style={{ width: '160px', maxWidth: '100%', height: 'auto' }}>
                              {[0, 1, 2, 3, 4, 5, 6].map(row => <line key={`fret-${row}`} x1="40" y1={40 + row * 32} x2="200" y2={40 + row * 32} stroke="var(--border-color)" strokeWidth={row === 0 && diagramBase === 1 ? 4 : 1.5} />)}
                              {[0, 1, 2, 3, 4, 5].map(string => <line key={`string-${string}`} x1={40 + string * 32} y1="40" x2={40 + string * 32} y2="232" stroke="var(--text-muted)" strokeOpacity="0.55" strokeWidth="1.5" />)}
                              {diagramBase > 1 && <text x="15" y="58" fill="var(--accent)" fontSize="12" textAnchor="middle">{diagramBase}fr</text>}
                              {STRINGS.map((string, index) => {
                                const fret = voicing.frets[index];
                                const x = 40 + index * 32;
                                if (fret === null) return <text key={`mute-${index}`} x={x} y="30" fill="var(--text-muted)" fontSize="12" textAnchor="middle">×</text>;
                                if (fret === 0) return <circle key={`open-${index}`} cx={x} cy="26" r="5" fill="none" stroke="var(--text-secondary)" strokeWidth="2" />;
                                const relativeFret = fret - diagramBase + 1;
                                if (relativeFret < 1 || relativeFret > 6) return null;
                                const note = voicing.notes.find(item => item.string === index);
                                return <g key={`note-${index}`}><circle cx={x} cy={40 + (relativeFret - 0.5) * 32} r="12" fill="var(--accent)" /><text x={x} y={44 + (relativeFret - 0.5) * 32} fill="var(--text-on-accent)" fontSize="9" fontWeight="700" textAnchor="middle">{note?.pitchClass ?? string}</text></g>;
                              })}
                              {STRINGS.map((string, index) => <text key={`label-${index}`} x={40 + index * 32} y="258" fill="var(--text-muted)" fontSize="10" textAnchor="middle">{string}</text>)}
                            </svg>
                          </div>
                          <div style={{ color: 'var(--text-secondary)', fontSize: '13px', lineHeight: 1.6 }}>
                            <div>{STRINGS.map((string, index) => `${string}:${voicing.frets[index] === null ? 'x' : voicing.frets[index]}`).join('  ')}</div>
                            <div>{t.chordExplorer.bass}: <strong>{voicing.bassNote}</strong> · {t.chordExplorer.fretSpan}: {voicing.fretSpan}</div>
                            <div>{t.chordExplorer.notes}: {voicing.notes.map(note => `${note.pitchClass} (${note.intervalLabel})`).join(' · ')}</div>
                            <div>{t.chordExplorer.fingers}: {voicing.fingering.fingers.map((finger, index) => voicing.frets[index] === null ? 'x' : finger || '–').join(' ')}</div>
                          </div>
                          <button type="button" onClick={() => setReferenceVoicingId(voicing.id)} style={{ minHeight: '40px', border: '1px solid var(--border-color)', background: 'transparent', color: 'var(--text-secondary)', borderRadius: '8px', cursor: 'pointer' }}>
                            {t.chordExplorer.compareFrom}
                          </button>
                        </article>
                      );
                    })}
                  </div>
                )}
              </section>
            </div>
          </div>

          <div>
<div style={{ fontSize: '12px', color: 'var(--text-muted)', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: '10px' }}>{t.chordDictionary.category}</div>
            {/* 🔥 ИЗМЕНЕНО: на мобильном категории — горизонтальная лента чипов
                (scroll-x), а не вертикальный список на всю ширину — экономит
                высоту экрана в пользу самой диаграммы аккорда ниже. */}
            <div style={{ display: 'flex', flexDirection: isMobile ? 'row' : 'column', gap: '6px', overflowX: isMobile ? 'auto' : 'visible', WebkitOverflowScrolling: 'touch', paddingBottom: isMobile ? '2px' : 0 }}>
              {Object.keys(CHORD_CATEGORIES).map(cat => (
                <button
                  key={cat}
                  onClick={() => {
                    setActiveCategory(cat as any);
                    setSelectedSuffix(CHORD_CATEGORIES[cat as keyof typeof CHORD_CATEGORIES][0].suffix);
                  }}
                  style={{ background: activeCategory === cat ? 'var(--bg-hover)' : 'transparent', color: activeCategory === cat ? 'var(--accent)' : 'var(--text-secondary)', border: `1px solid ${isMobile ? 'var(--border-color)' : 'transparent'}`, padding: '10px 14px', minHeight: '44px', borderRadius: '8px', fontWeight: 700, fontSize: '14px', textAlign: 'left', cursor: 'pointer', transition: '0.15s', whiteSpace: 'nowrap', flexShrink: 0 }}
                >
                  {cat === 'Major' ? '🟢 ' : cat === 'Minor' ? '🔵 ' : cat === 'Dominant' ? '🟡 ' : '🔴 '}
                  {cat}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div style={{ width: isMobile ? '100%' : '300px', borderRight: isMobile ? 'none' : '1px solid var(--border-color)', borderBottom: isMobile ? '1px solid var(--border-color)' : 'none', padding: isMobile ? '16px' : '20px', overflowY: isMobile ? 'visible' : 'auto', display: 'flex', flexDirection: 'column', gap: '8px', flexShrink: 0 }}>
<div style={{ fontSize: '12px', color: 'var(--text-muted)', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: '4px' }}>{t.chordDictionary.selectExtensions}</div>
          {/* 🔥 ИЗМЕНЕНО: на мобильном — тоже горизонтальная лента чипов вместо
              списка широких строк (тот же приём, что и для категорий). */}
          <div style={{ display: 'flex', flexDirection: isMobile ? 'row' : 'column', gap: '8px', overflowX: isMobile ? 'auto' : 'visible', WebkitOverflowScrolling: 'touch' }}>
            {CHORD_CATEGORIES[activeCategory].map(item => (
              <button
                key={item.suffix}
                onClick={() => setSelectedSuffix(item.suffix)}
                style={{ background: selectedSuffix === item.suffix ? 'var(--bg-primary)' : 'transparent', color: selectedSuffix === item.suffix ? 'var(--accent)' : 'var(--text-primary)', border: `1px solid ${selectedSuffix === item.suffix ? 'var(--border-color)' : (isMobile ? 'var(--border-color)' : 'transparent')}`, padding: '12px 16px', minHeight: '48px', borderRadius: '8px', fontWeight: 700, fontSize: '14px', textAlign: 'left', cursor: 'pointer', transition: '0.15s', display: 'flex', flexDirection: isMobile ? 'column' : 'row', gap: isMobile ? '2px' : '0', justifyContent: 'space-between', alignItems: isMobile ? 'flex-start' : 'center', whiteSpace: isMobile ? 'nowrap' : 'normal', flexShrink: 0 }}
                onMouseEnter={e => { if(selectedSuffix !== item.suffix) e.currentTarget.style.background = 'var(--bg-secondary)'; }}
                onMouseLeave={e => { if(selectedSuffix !== item.suffix) e.currentTarget.style.background = 'transparent'; }}
              >
                <span>{selectedRoot}{item.suffix || ' (maj)'}</span>
                <span style={{ fontSize: '11px', color: 'var(--text-muted)', fontWeight: 'normal' }}>{item.label}</span>
              </button>
            ))}
          </div>
        </div>

        <div style={{ flex: 1, padding: isMobile ? '20px 16px' : '24px', overflowY: isMobile ? 'visible' : 'auto', display: 'flex', flexDirection: 'column', alignItems: 'center', background: 'var(--bg-root)' }}>
          <div style={{ textAlign: 'center', marginBottom: '20px' }}>
            <h2 style={{ fontSize: isMobile ? '30px' : '36px', fontWeight: 800, margin: '0 0 4px 0', color: 'var(--accent)' }}>
              {currentChordName}
            </h2>
          </div>

          {voicings.map((voicing, vIdx) => (
            <div key={vIdx} style={{ background: 'var(--bg-panel)', border: '1px solid var(--border-color)', padding: '20px', borderRadius: '12px', width: '100%', maxWidth: '340px', display: 'flex', flexDirection: 'column', gap: '16px', marginBottom: '20px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '12px', fontWeight: 800, color: 'var(--text-secondary)', borderBottom: '1px solid var(--border-color)', paddingBottom: '8px' }}>
<span>{t.chordDictionary.pos} {voicing.name}</span>
                <button
                  onClick={() => playChordAudio(voicing.frets)}
                  style={{ background: 'var(--bg-secondary)', color: 'var(--accent)', border: '1px solid var(--accent)', padding: '4px 12px', minHeight: '40px', borderRadius: '20px', fontSize: '12px', fontWeight: 800, cursor: 'pointer', display: 'flex', gap: '4px', alignItems: 'center', transition: '0.2s' }}
                  onMouseEnter={e => { e.currentTarget.style.background = 'var(--accent)'; e.currentTarget.style.color = '#000'; }}
                  onMouseLeave={e => { e.currentTarget.style.background = 'var(--bg-secondary)'; e.currentTarget.style.color = 'var(--accent)'; }}
                >
{t.chordDictionary.listen}
                </button>
              </div>

              <div style={{ display: 'flex', justifyContent: 'space-between', background: 'var(--bg-primary)', padding: '8px 12px', borderRadius: '6px', fontFamily: 'monospace', fontSize: '12px', fontWeight: 700, color: 'var(--text-muted)' }}>
                {voicing.frets.map((f, idx) => (
                  <span key={idx} style={{ color: f !== 'x' ? 'var(--text-primary)' : 'var(--text-muted)' }}>
                    {STRINGS[idx]}:{f}
                  </span>
                ))}
              </div>

              <div style={{ display: 'flex', justifyContent: 'center', padding: '10px 0', background: 'var(--bg-primary)', borderRadius: '8px', border: '1px solid var(--border-color)' }}>
                <svg viewBox="0 0 240 280" style={{ width: '180px', height: 'auto', display: 'block' }}>
                  {[0, 1, 2, 3, 4, 5].map((i) => (
                    <line key={`fline-${i}`} x1="40" y1={50 + i * 40} x2="200" y2={50 + i * 40} stroke={voicing.baseFret === 1 && i === 0 ? "#d8dfda" : "rgba(216,223,218,0.58)"} strokeWidth={voicing.baseFret === 1 && i === 0 ? "4" : "1.5"} />
                  ))}
                  {[0, 1, 2, 3, 4, 5].map((i) => (
                    <line key={`sline-${i}`} x1={40 + i * 32} y1="50" x2={40 + i * 32} y2="250" stroke="rgba(216,223,218,0.42)" strokeWidth={1 + i * 0.3} />
                  ))}
                  {voicing.baseFret > 1 && (
                    <text x="15" y="75" fill="var(--accent)" fontSize="12" fontWeight="800" textAnchor="middle">{voicing.baseFret}fr</text>
                  )}
                  {STRINGS.map((letter, i) => (
                    <text key={`lbl-${i}`} x={40 + i * 32} y="270" fill="var(--text-muted)" fontSize="11" fontWeight="800" textAnchor="middle">{letter}</text>
                  ))}
                  {voicing.frets.map((fretVal, stringIdx) => {
                    const gridX = 40 + stringIdx * 32;
                    if (fretVal === 'x') return <text key={`x-${stringIdx}`} x={gridX} y="38" fill="#ff4d4d" fontSize="14" fontWeight="900" textAnchor="middle">✕</text>;
                    if (fretVal === 0) return <circle key={`o-${stringIdx}`} cx={gridX} cy={34} r="5" fill="transparent" stroke="var(--text-secondary)" strokeWidth="2" />;
                    const relativeFret = fretVal - voicing.baseFret + 1;
                    const gridY = 50 + (relativeFret - 1) * 40 + 20;
                    if (relativeFret >= 1 && relativeFret <= 5) {
                      return (
                        <g key={`dot-${stringIdx}`}>
                          <circle cx={gridX} cy={gridY} r="11" fill="var(--accent)" style={{ filter: 'drop-shadow(0 0 6px var(--accent))' }} />
                          <text x={gridX} y={gridY + 4} fill="#000000" fontSize="11" fontWeight="900" textAnchor="middle">{fretVal}</text>
                        </g>
                      );
                    }
                    return null;
                  })}
                </svg>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default ChordDictionary;