interface PluckedGuitarChordOptions {
  context: BaseAudioContext;
  frequencies: readonly number[];
  startTime: number;
  duration: number;
  velocity: number;
  strumDelay: number;
  connect: (gain: GainNode) => void;
}

export const playPluckedGuitarChord = ({
  context,
  frequencies,
  startTime,
  duration,
  velocity,
  strumDelay,
  connect,
}: PluckedGuitarChordOptions): OscillatorNode[] => {
  if (!Number.isFinite(duration) || duration <= 0 || !Number.isFinite(startTime)) return [];

  const oscillators: OscillatorNode[] = [];
  frequencies.forEach((frequency, index) => {
    if (!Number.isFinite(frequency) || frequency <= 0) return;

    const noteStartTime = startTime + index * strumDelay;
    const noteEndTime = noteStartTime + duration;
    const attackDuration = Math.min(0.01, duration / 2);
    const oscillator = context.createOscillator();
    const gain = context.createGain();

    oscillator.type = 'triangle';
    oscillator.frequency.setValueAtTime(frequency, noteStartTime);
    gain.gain.setValueAtTime(0, noteStartTime);
    gain.gain.linearRampToValueAtTime(velocity, noteStartTime + attackDuration);
    gain.gain.exponentialRampToValueAtTime(0.001, noteEndTime);
    oscillator.connect(gain);
    connect(gain);
    oscillator.start(noteStartTime);
    oscillator.stop(noteEndTime);
    oscillators.push(oscillator);
  });

  return oscillators;
};
