import { useState, useEffect, useRef } from 'react';
import type React from 'react';
import { isMusicMode, MUSIC_MODES, useMusic } from '../../context/MusicContext';
import { playNote } from '../../utils/audioEngine';
import { Button } from '../ui/Button';
import { useTranslation } from '../../context/LocaleContext';
import { getScaleById, LEGACY_SCALE_IDS, SCALE_FAMILIES, SCALES } from '../../data/scales';
import { getTargetNotes, type TargetNoteRole } from '../../engines/TargetNoteEngine';
import PracticeMode from './PracticeMode';

const TUNINGS: Record<string, string[]> = {
  'Standard E': ['E', 'A', 'D', 'G', 'B', 'E'],
  'Drop D': ['D', 'A', 'D', 'G', 'B', 'E'],
  'Drop C': ['C', 'G', 'C', 'F', 'A', 'D'],
  'D Standard': ['D', 'G', 'C', 'F', 'A', 'D'],
};

const MATERIALS = {
  ebony: { bg: '#1a1a1a', dot: '#e0e0e0', fretDark: '#111215', fretLight: '#c0c0c0' },
  rosewood: { bg: '#3e2723', dot: '#d7ccc8', fretDark: '#211512', fretLight: '#d7ccc8' },
  maple: { bg: '#f1ba54', dot: '#3e2723', fretDark: '#5c4314', fretLight: '#fafafa' },
  glass: { bg: 'rgba(255,255,255,0.04)', dot: '#d7ccc8', fretDark: 'rgba(255,255,255,0.15)', fretLight: 'var(--accent)' },
};

const ALL_NOTES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const STRING_GAUGES = [1.2, 1.8, 2.4, 3.2, 4.2, 5.4];
const INTERVAL_MAP = ['1', 'b2', '2', 'b3', '3', '4', 'b5', '5', 'b6', '6', 'b7', '7'];

type DisplayMode = 'notes' | 'intervals' | 'caged' | 'clean';

const DISPLAY_MODES: { value: DisplayMode; label: string }[] = [
  { value: 'notes', label: '🎵 Notes' },
  { value: 'intervals', label: '🔢 Intervals' },
  { value: 'caged', label: '🦴 CAGED' },
  { value: 'clean', label: '⏺ Clean' },
];

const Fretboard: React.FC = () => {
  const { t, locale } = useTranslation();
  const { keyNote, mode, getScaleNotes, setKeyNote, setMode } = useMusic();
  const [selectedScaleId, setSelectedScaleId] = useState<string>(() => LEGACY_SCALE_IDS[mode] ?? 'minor');
  const [practiceScaleRoot, setPracticeScaleRoot] = useState(keyNote);
  const [practiceOpen, setPracticeOpen] = useState(false);
  const [activePracticeChord, setActivePracticeChord] = useState('Cmaj7');
  const [targetPosition, setTargetPosition] = useState(5);
  const [showPassingNotes, setShowPassingNotes] = useState(false);
  const selectedScale = getScaleById(selectedScaleId);
  const keyIndex = ALL_NOTES.indexOf(keyNote);
  const selectedMode = MUSIC_MODES.find(option => option.value === selectedScaleId);
  const scaleRootIndex = practiceOpen ? ALL_NOTES.indexOf(practiceScaleRoot) : keyIndex;
  const scaleNotes = selectedMode?.group === 'arpeggio'
    ? getScaleNotes()
    : scaleRootIndex < 0
      ? getScaleNotes()
    : selectedScale.intervals.map(interval => ALL_NOTES[(scaleRootIndex + interval) % 12]);
  const targetNoteMap = practiceOpen
    ? new Map(getTargetNotes(activePracticeChord, selectedScaleId, 'weak', practiceScaleRoot)
      .filter(target => target.role === 'root' || target.role === 'chordTone'
        || (showPassingNotes && (target.role === 'tension' || target.role === 'passing')))
      .map(target => [target.pitch, target.role]))
    : null;
  const [tuningName, setTuningName] = useState<string>('Standard E');
  const [material, setMaterial] = useState<keyof typeof MATERIALS>('glass');
  const [fretColor, setFretColor] = useState<'dark' | 'light'>('dark');
  const [displayMode, setDisplayMode] = useState<DisplayMode>('notes');
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);
  const [hoveredNote, setHoveredNote] = useState<string | null>(null);
  const fretboardScrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);
  useEffect(() => {
    const container = fretboardScrollRef.current;
    if (!practiceOpen || !container) return;
    const fretWidth = (container.scrollWidth - 40) / 25;
    const positionCenter = 40 + (targetPosition + 2) * fretWidth;
    container.scrollTo({
      left: Math.max(0, positionCenter - container.clientWidth / 2),
      behavior: 'smooth',
    });
  }, [practiceOpen, targetPosition]);

  const strings = TUNINGS[tuningName].slice().reverse();
  const frets = Array.from({ length: 25 }, (_, i) => i);
  const dots = [3, 5, 7, 9, 15, 17, 19, 21];
  const doubleDots = [12, 24];
  const currentMat = MATERIALS[material];
  const currentFretColor = fretColor === 'dark' ? currentMat.fretDark : currentMat.fretLight;
const isCyberpunk = material === 'glass' && fretColor === 'light';

  useEffect(() => {
    const currentMode = MUSIC_MODES.find(option => option.value === mode);
    setSelectedScaleId(currentMode?.group === 'arpeggio' ? mode : LEGACY_SCALE_IDS[mode] ?? 'minor');
  }, [mode]);
  useEffect(() => setPracticeScaleRoot(keyNote), [keyNote]);

  const handleScaleChange = (scaleId: string, root: string = keyNote) => {
    setSelectedScaleId(scaleId);
    setPracticeScaleRoot(root);
    if (isMusicMode(scaleId)) {
      setMode(scaleId);
      return;
    }
    const legacyMode = Object.keys(LEGACY_SCALE_IDS).find(id =>
      LEGACY_SCALE_IDS[id] === scaleId && isMusicMode(id),
    );
    if (legacyMode && isMusicMode(legacyMode)) setMode(legacyMode);
  };

  const getTargetColor = (role: TargetNoteRole): string => {
    switch (role) {
      case 'root': return '#58a6ff';
      case 'chordTone': return '#5ed58b';
      case 'tension': return '#f4c95d';
      case 'passing': return '#a8afb9';
      case 'outside': return '#626a75';
    }
  };

  const getNoteAtFret = (openNote: string, fret: number) =>
    ALL_NOTES[(ALL_NOTES.indexOf(openNote) + fret) % 12];

  const handleNoteClick = (note: string) => {
    playNote(note, 0.8, 0.35);
  };

  const getFretLabel = (note: string): string => {
    if (displayMode === 'notes') return note;
    if (displayMode === 'intervals') {
      const intervalRoot = practiceOpen ? practiceScaleRoot : keyNote;
      const diff = (ALL_NOTES.indexOf(note) - ALL_NOTES.indexOf(intervalRoot) + 12) % 12;
      return INTERVAL_MAP[diff];
    }
    if (displayMode === 'caged') return note;
    return '';
  };

  const getFretStyle = (note: string): React.CSSProperties => {
    const targetRole = targetNoteMap?.get(note);
    const isRoot = practiceOpen ? targetRole === 'root' : note === keyNote;
    const noteAlpha = '1';
    const base = { width: '24px', height: '24px', fontSize: '11px', fontWeight: '900' };

    if (targetRole) {
      return {
        ...base,
        borderRadius: targetRole === 'chordTone' ? '4px' : '50%',
        background: getTargetColor(targetRole),
        color: targetRole === 'outside' ? '#fff' : '#101216',
        border: targetRole === 'tension' ? '2px dashed #7b5d10' : targetRole === 'passing' ? '1px solid #48505a' : '1px solid rgba(0,0,0,0.28)',
        boxShadow: targetRole === 'root' ? '0 0 8px rgba(88,166,255,0.6)' : '0 2px 4px rgba(0,0,0,0.35)',
      };
    }

    if (displayMode === 'notes' || displayMode === 'intervals') {
      return {
        ...base,
        borderRadius: '50%',
        background: isRoot ? 'var(--accent)' : `rgba(255,255,255,${noteAlpha})`,
        color: isRoot ? '#000' : '#111216',
        boxShadow: isRoot ? '0 0 8px var(--color-accent-glow), 0 2px 4px rgba(0,0,0,0.5)' : '0 2px 4px rgba(0,0,0,0.4)',
      };
    }
    if (displayMode === 'caged') {
      const isMaple = material === 'maple';
      if (isRoot) {
        return {
          ...base,
          borderRadius: '4px',
          background: 'var(--accent)',
          color: '#000',
          boxShadow: '0 0 8px var(--color-accent-glow)',
        };
      }
      return {
        ...base,
        borderRadius: '4px',
        background: isMaple ? 'rgba(0,0,0,0.18)' : 'rgba(255,255,255,0.32)',
        border: `1px solid ${isMaple ? '#5c4314' : 'rgba(255,255,255,0.4)'}`,
        color: isMaple ? '#5c4314' : 'var(--text-primary)',
      };
    }
    // clean
    return {
      ...base,
      borderRadius: '50%',
      background: isRoot ? 'var(--accent)' : `rgba(255,255,255,${noteAlpha})`,
      boxShadow: isRoot ? '0 0 8px var(--color-accent-glow)' : 'none',
    };
  };

  return (
    <div style={{
      background: 'var(--bg-panel)',
      borderRadius: 'var(--radius)',
padding: isMobile ? '12px' : '16px',
      border: '1px solid var(--border-color)',
    }}>

{/* ── Header: title ── */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        marginBottom: '16px',
        flexWrap: 'wrap',
        gap: '8px',
      }}>
        <span className="fl-section-label" style={{ color: 'var(--accent)', fontSize: '13px', letterSpacing: '1px' }}>
          {t.fretboard.title}
        </span>
        <Button
          variant={practiceOpen ? 'secondary' : 'ghost'}
          active={practiceOpen}
          size="sm"
          onClick={() => setPracticeOpen(value => !value)}
          aria-pressed={practiceOpen}
        >
          {practiceOpen ? (locale === 'ru' ? 'Закрыть практику' : 'Close practice') : (locale === 'ru' ? 'Practice · Импровизация' : 'Practice · Improvise')}
        </Button>
      </div>

      {/* ── Controls row (single row on desktop) ── */}
      <div className="fl-section-panel" style={{ marginBottom: '16px', justifyContent: 'space-between' }}>
        {/* Left: key + mode + display mode toggle */}
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', alignItems: 'center' }}>
          <select
            value={keyNote}
            onChange={(e) => setKeyNote(e.target.value)}
            className="fl-select"
            aria-label={t.fretboard.key}
          >
            {ALL_NOTES.map(n => <option key={n} value={n}>{n}</option>)}
          </select>

          <select
            value={selectedScaleId}
            onChange={(e) => handleScaleChange(e.target.value)}
            className="fl-select"
            style={{ maxWidth: isMobile ? '120px' : '160px' }}
            aria-label={locale === 'ru' ? 'Гамма' : 'Scale'}
          >
            {SCALE_FAMILIES.map(family => (
              <optgroup key={family.id} label={locale === 'ru' ? family.ru : family.en}>
                {SCALES.filter(scale => scale.family === family.id).map(scale => (
                  <option key={scale.id} value={scale.id} title={`${scale.commonUse} · Level ${scale.difficulty}/5`}>
                    {scale.name}
                  </option>
                ))}
              </optgroup>
            ))}
          </select>

          {/* Display mode toggle */}
          <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap' }}>
            {DISPLAY_MODES.map(dm => (
              <Button
                key={dm.value}
                variant={displayMode === dm.value ? 'secondary' : 'ghost'}
                active={displayMode === dm.value}
                size="sm"
                onClick={() => setDisplayMode(dm.value)}
                aria-pressed={displayMode === dm.value}
              >
                {dm.label}
              </Button>
            ))}
          </div>
        </div>

        {/* Right: tuning + material + fret color */}
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', alignItems: 'center' }}>
          <select
            value={tuningName}
            onChange={(e) => setTuningName(e.target.value)}
            className="fl-select"
            aria-label={t.fretboard.tuning}
          >
            {Object.keys(TUNINGS).map(t => <option key={t} value={t}>{t}</option>)}
          </select>

          <select
            value={material}
            onChange={(e) => setMaterial(e.target.value as any)}
            className="fl-select"
            aria-label={t.fretboard.neck}
          >
            {Object.keys(MATERIALS).map(m => <option key={m} value={m}>{m.charAt(0).toUpperCase() + m.slice(1)} Neck</option>)}
          </select>

          <select
            value={fretColor}
            onChange={(e) => setFretColor(e.target.value as any)}
            className="fl-select"
            aria-label={t.fretboard.frets}
          >
            <option value="dark">Dark Frets</option>
            <option value="light">Light Frets</option>
          </select>
        </div>
      </div>

      {practiceOpen && (
        <PracticeMode
          keyNote={keyNote}
          scaleId={selectedScaleId}
          locale={locale}
          onScaleChange={handleScaleChange}
          onChordChange={setActivePracticeChord}
          targetPosition={targetPosition}
          showPassingNotes={showPassingNotes}
          onTargetPositionChange={setTargetPosition}
          onShowPassingNotesChange={setShowPassingNotes}
        />
      )}

      {/* ── Fretboard grid ── */}
      <div ref={fretboardScrollRef} style={{ overflowX: 'auto', overflowY: 'hidden', WebkitOverflowScrolling: 'touch', touchAction: 'pan-x' }}>
        <div style={{ minWidth: isMobile ? '600px' : '800px' }}>

          {/* Fret numbers top */}
          <div style={{ display: 'flex', paddingLeft: '40px', marginBottom: '6px' }}>
            {frets.map(f => (
              <div key={`top-${f}`} style={{ flex: 1, textAlign: 'center', color: 'var(--text-muted)', fontSize: '10px', fontWeight: 800 }}>
                {f}
              </div>
            ))}
          </div>

          {/* Main grid */}
          <div style={{
            position: 'relative',
            background: '#000',
            border: '2px solid #000',
            borderRadius: '4px',
            display: 'flex',
            flexDirection: 'column',
          }}>

            {/* Background board */}
            <div style={{
              position: 'absolute',
              top: '18px', left: '40px', right: 0, bottom: '18px',
              background: currentMat.bg,
              zIndex: 0,
              pointerEvents: 'none',
            }} />

            {/* Fret lines + position dots */}
            <div style={{
              position: 'absolute',
              top: '18px', left: '40px', right: 0, bottom: '18px',
              display: 'flex',
              pointerEvents: 'none',
              zIndex: 1,
            }}>
              {frets.map(f => (
                <div key={`dotcol-${f}`} style={{ flex: 1, position: 'relative', borderRight: f === 0 ? '4px solid #bba182' : `${isCyberpunk ? 'transparent' : '1px'} solid ${isCyberpunk ? 'transparent' : currentFretColor}` }}>
                  {isCyberpunk && f !== 0 && (
                    <div style={{
                      position: 'absolute', right: '-1px', top: 0, bottom: 0, width: '1px',
                      background: 'var(--accent)',
                      boxShadow: '0 0 3px var(--accent)',
                      opacity: 0.3,
                    }} />
                  )}
                  {dots.includes(f) && (
                    <div style={{
                      position: 'absolute', top: '50%', left: '50%',
                      transform: 'translate(-50%, -50%)',
                      width: '12px', height: '12px', borderRadius: '50%',
                      background: currentMat.dot,
                      boxShadow: isCyberpunk ? '0 0 4px var(--accent)' : 'none',
                    }} />
                  )}
                  {doubleDots.includes(f) && (
                    <>
                      <div style={{ position: 'absolute', top: '30%', left: '50%', transform: 'translate(-50%, -50%)', width: '12px', height: '12px', borderRadius: '50%', background: currentMat.dot }} />
                      <div style={{ position: 'absolute', top: '70%', left: '50%', transform: 'translate(-50%, -50%)', width: '12px', height: '12px', borderRadius: '50%', background: currentMat.dot }} />
                    </>
                  )}
                </div>
              ))}
            </div>

            {/* Strings + notes */}
            {strings.map((openNote, stringIdx) => {
              const thickness = STRING_GAUGES[stringIdx];
              return (
                <div key={stringIdx} style={{ display: 'flex', alignItems: 'center', position: 'relative', height: '36px' }}>
                  {/* String line */}
                  <div style={{
                    position: 'absolute', left: 0, right: 0,
                    height: `${thickness}px`,
                    background: 'linear-gradient(to bottom, #777, #999, #555)',
                    zIndex: 2,
                    boxShadow: '0 2px 4px rgba(0,0,0,0.5)',
                  }} />
                  {/* Open note label */}
                  <div style={{
                    width: '40px', textAlign: 'center',
                    fontWeight: 800, color: 'var(--text-muted)',
                    zIndex: 3, background: 'var(--bg-panel)',
                    fontFamily: 'var(--font-mono)',
                  }}>
                    {openNote}
                  </div>

                  {/* Frets */}
                  {frets.map(fret => {
                    const note = getNoteAtFret(openNote, fret);
                    const isInScale = scaleNotes.includes(note);
                    const targetRole = targetNoteMap?.get(note);
                    const isVisible = targetNoteMap
                      ? targetRole !== undefined && fret >= targetPosition && fret <= targetPosition + 4
                      : isInScale;
                    const isRoot = practiceOpen ? targetRole === 'root' : note === keyNote;
                    const label = getFretLabel(note);
                    const fretStyle = getFretStyle(note);
                    const isHovered = hoveredNote === `${note}-${stringIdx}-${fret}`;

                    return (
                      <div
                        key={`${stringIdx}-${fret}`}
                        style={{ flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 3, position: 'relative' }}
                        onMouseEnter={() => setHoveredNote(`${note}-${stringIdx}-${fret}`)}
                        onMouseLeave={() => setHoveredNote(null)}
                      >
                        {isVisible && (
                          <button
                            type="button"
                            onClick={() => handleNoteClick(note)}
                            aria-label={`${note}${isRoot ? ` ${t.fretboard.tonic}` : ''}${targetRole ? `, ${locale === 'ru' ? 'роль' : 'role'}: ${targetRole}` : ''}`}
                            title={`${note}${targetRole ? ` · ${targetRole}` : ''}`}
                            style={{
                              display: 'flex', alignItems: 'center', justifyContent: 'center',
                              border: 'none', cursor: 'pointer',
                              transform: isHovered ? 'scale(1.18)' : 'scale(1)',
                              transition: 'transform 0.1s ease',
                              ...fretStyle,
                            }}
                          >
                            {label}
                          </button>
                        )}
                      </div>
                    );
                  })}
                </div>
              );
            })}
          </div>

          {/* Fret numbers bottom */}
          <div style={{ display: 'flex', paddingLeft: '40px', marginTop: '6px' }}>
            {frets.map(f => (
              <div key={`bottom-${f}`} style={{ flex: 1, textAlign: 'center', color: 'var(--text-muted)', fontSize: '10px', fontWeight: 800 }}>
                {f}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Fretboard;
