import type {
  BassBeatEvent,
  DrumBeatEvent,
  FretLabArrangement,
  FretLabGenre,
  MelodyBeatEvent,
} from '../types/song';
import { getStyleRule, type StyleRule } from './styleRules';

export type MelodyRhythm = 'style' | 'eighths' | 'syncopated' | 'triplets' | 'dotted' | 'long';

export interface GeneratedMelodyEvent extends MelodyBeatEvent {
  accent: boolean;
  duration: string;
}

interface RhythmSlot {
  beat: number;
  durationBeats: number;
  accent: boolean;
  cadence?: boolean;
}

const rhythmTemplate = (
  beats: number[],
  durations: number[],
  accents: number[],
): RhythmSlot[] => beats.map((beat, index) => ({
  beat,
  durationBeats: durations[index],
  accent: accents.includes(index),
}));

const SHUFFLE_RHYTHMS = [
  rhythmTemplate([0, 0.75, 2, 3], [0.65, 0.28, 0.65, 0.85], [0, 2, 3]),
  rhythmTemplate([0, 1, 2.25, 3.25], [0.8, 0.35, 0.55, 0.55], [0, 2]),
  rhythmTemplate([0, 0.5, 1.5, 2.5], [0.65, 0.28, 0.5, 0.7], [0, 3]),
  rhythmTemplate([0, 1.25, 2, 3], [0.75, 0.4, 0.65, 0.65], [0, 2, 3]),
];

const STYLE_RHYTHM_TEMPLATES: Record<FretLabGenre, RhythmSlot[][]> = {
  Rock: [
    rhythmTemplate([0, 1.5, 2.5, 3.25], [0.85, 0.65, 0.45, 0.55], [0, 2, 3]),
    rhythmTemplate([0, 1, 2, 3.5], [0.75, 0.4, 0.75, 0.35], [0, 2]),
    rhythmTemplate([0, 0.75, 2, 2.75], [0.65, 0.3, 0.75, 0.55], [0, 2]),
    rhythmTemplate([0, 1.75, 2.5], [0.85, 0.45, 0.9], [0, 2]),
  ],
  'Hard Rock': [
    rhythmTemplate([0, 1, 2, 3.25], [0.8, 0.42, 0.8, 0.5], [0, 2]),
    rhythmTemplate([0, 0.75, 2, 3], [0.7, 0.3, 0.8, 0.65], [0, 2, 3]),
    rhythmTemplate([0, 1.5, 2.5, 3.5], [0.8, 0.5, 0.7, 0.35], [0, 2]),
    rhythmTemplate([0, 0.5, 2, 2.75, 3.5], [0.4, 0.35, 0.75, 0.3, 0.35], [0, 2]),
  ],
  Metal: [
    rhythmTemplate([0, 0.75, 1.5, 2, 2.75, 3.5], [0.62, 0.22, 0.22, 0.62, 0.22, 0.22], [0, 3]),
    rhythmTemplate([0, 0.5, 1.25, 2, 2.5, 3.25], [0.4, 0.25, 0.3, 0.65, 0.25, 0.4], [0, 3]),
    rhythmTemplate([0, 0.75, 1.25, 2, 2.75, 3], [0.6, 0.2, 0.3, 0.6, 0.2, 0.55], [0, 3, 5]),
    rhythmTemplate([0, 0.5, 1, 1.75, 2, 3.5], [0.5, 0.25, 0.35, 0.2, 0.65, 0.3], [0, 4]),
  ],
  'Thrash Metal': [
    rhythmTemplate([0, 0.75, 1.5, 2, 2.75, 3.5], [0.62, 0.22, 0.22, 0.62, 0.22, 0.22], [0, 3]),
    rhythmTemplate([0, 0.5, 1.25, 2, 2.5, 3.25], [0.4, 0.25, 0.3, 0.65, 0.25, 0.4], [0, 3]),
    rhythmTemplate([0, 0.5, 1, 1.5, 2, 3], [0.5, 0.2, 0.25, 0.25, 0.6, 0.55], [0, 4, 5]),
    rhythmTemplate([0, 0.75, 1.25, 2, 2.5, 3.5], [0.6, 0.2, 0.3, 0.6, 0.25, 0.3], [0, 3]),
  ],
  'Groove Metal': [
    rhythmTemplate([0, 1.5, 2.25, 3], [0.75, 0.35, 0.45, 0.65], [0, 3]),
    rhythmTemplate([0, 0.75, 2, 3.25], [0.65, 0.3, 0.75, 0.5], [0, 2]),
    rhythmTemplate([0, 1.25, 2.5, 3], [0.8, 0.4, 0.5, 0.65], [0, 3]),
    rhythmTemplate([0, 1.5, 2.25, 3.5], [0.7, 0.35, 0.5, 0.35], [0, 2]),
  ],
  Blues: SHUFFLE_RHYTHMS,
  'Blues Rock': SHUFFLE_RHYTHMS,
  Funk: [
    rhythmTemplate([0, 0.75, 1.5, 2, 2.75, 3.5], [0.35, 0.25, 0.35, 0.35, 0.25, 0.35], [0, 3]),
    rhythmTemplate([0, 0.5, 1.25, 2, 2.5, 3.25], [0.35, 0.2, 0.3, 0.35, 0.25, 0.4], [0, 3]),
    rhythmTemplate([0, 1, 1.75, 2.5, 3, 3.5], [0.45, 0.25, 0.25, 0.35, 0.25, 0.3], [0, 3]),
    rhythmTemplate([0, 0.75, 1.5, 2, 3, 3.25], [0.35, 0.25, 0.35, 0.35, 0.3, 0.25], [0, 3]),
  ],
};

interface BassPatternSlot {
  beat: number;
  tone: 0 | 1 | 2;
  duration: number;
}

interface DrumGroove {
  kick: number[];
  snare: number[];
  ghostSnare?: number[];
  hats: number[];
  ride?: number[];
}

const NOTE_NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const ENHARMONIC_MAP: Record<string, string> = {
  Db: 'C#', Eb: 'D#', Gb: 'F#', Ab: 'G#', Bb: 'A#',
};
const GUITAR_OPEN_MIDI = [64, 59, 55, 50, 45, 40];
const MELODIC_CONTOURS = [
  [1, -1, 2, -1, 1, 2, -2, -1],
  [2, 1, -1, -2, 1, 2, -1, -2],
  [-1, 2, 1, -1, 2, -2, 1, -1],
  [1, 2, -1, 1, -2, -1, 2, -1],
  [-2, 1, 1, 2, -1, -2, 1, 2],
  [2, -2, 1, 1, -1, 2, -2, -1],
  [-1, -2, 2, 1, -1, 2, 1, -2],
  [1, -2, 1, 2, -1, 1, -2, 2],
  [2, -1, -2, 1, 2, -1, 1, -2],
  [-2, 2, -1, 1, 1, -2, 2, -1],
  [1, 1, -2, 2, -1, 2, -1, -2],
  [-1, 2, -2, 1, 2, -1, -2, 1],
];
const STYLE_CONTOUR_INDICES: Record<FretLabGenre, number[]> = {
  Rock: [0, 1, 3],
  'Hard Rock': [1, 3, 4, 5],
  Metal: [4, 5, 7, 9],
  'Thrash Metal': [5, 6, 8, 11],
  'Groove Metal': [2, 4, 6, 9],
  Blues: [0, 2, 8, 10],
  'Blues Rock': [0, 3, 9, 10],
  Funk: [2, 6, 7, 11],
};

function seededRandom(seed: number): () => number {
  let value = seed >>> 0;
  return () => {
    value = (value + 0x6d2b79f5) >>> 0;
    let mixed = value;
    mixed = Math.imul(mixed ^ (mixed >>> 15), mixed | 1);
    mixed ^= mixed + Math.imul(mixed ^ (mixed >>> 7), mixed | 61);
    return ((mixed ^ (mixed >>> 14)) >>> 0) / 0x100000000;
  };
}

const MAJOR_PROGRESSIONS = [
  [0, 4, 5, 3],
  [0, 5, 3, 4],
  [1, 4, 0, 5],
  [0, 3, 1, 4],
  [5, 3, 0, 4],
];
const MINOR_PROGRESSIONS = [
  [0, 5, 2, 6],
  [0, 3, 6, 5],
  [0, 4, 5, 3],
  [0, 5, 3, 4],
  [3, 6, 0, 5],
];
const SHORT_SCALE_PROGRESSIONS = [
  [0, 3, 2, 1],
  [0, 2, 3, 1],
  [2, 3, 0, 1],
  [0, 1, 2, 3],
  [0, 3, 1, 2],
];

export function generateProgressionIndices(seed: number, chordCount: number, mode: string): number[] {
  const count = Math.max(1, Math.floor(chordCount));
  const random = seededRandom(seed + 83);
  const isMajorMode = mode === 'major' || mode === 'lydian' || mode === 'mixolydian';
  const templates = count >= 7
    ? isMajorMode ? MAJOR_PROGRESSIONS : MINOR_PROGRESSIONS
    : SHORT_SCALE_PROGRESSIONS;
  const template = templates[Math.floor(random() * templates.length)];

  return template.map(degree => degree % count);
}

function normalizePitch(note: string): string {
  const match = note.trim().match(/^[A-G](?:#|b)?/i);
  if (!match) return '';
  const pitch = match[0][0].toUpperCase() + match[0].slice(1);
  return ENHARMONIC_MAP[pitch] ?? pitch;
}

function pitchClass(note: string): number {
  return NOTE_NAMES.indexOf(normalizePitch(note));
}

function nearestScaleDegree(note: string, scale: string[]): number {
  const noteClass = pitchClass(note);
  if (noteClass < 0) return 0;

  return scale.reduce((nearest, candidate, index) => {
    const candidateClass = pitchClass(candidate);
    const nearestClass = pitchClass(scale[nearest]);
    const candidateDistance = Math.min(
      (candidateClass - noteClass + 12) % 12,
      (noteClass - candidateClass + 12) % 12,
    );
    const nearestDistance = Math.min(
      (nearestClass - noteClass + 12) % 12,
      (noteClass - nearestClass + 12) % 12,
    );
    return candidateDistance < nearestDistance ? index : nearest;
  }, 0);
}

function resolveRhythm(genre: FretLabGenre, rhythm: MelodyRhythm): 'eighths' | 'syncopated' | 'triplets' | 'dotted' | 'long' | 'shuffle' {
  if (rhythm !== 'style') return rhythm;

  const rule = getStyleRule(genre);
  if (rule.feel === 'shuffle' || rule.feel === 'swing') return 'shuffle';
  if (genre === 'Funk' || genre === 'Groove Metal') return 'syncopated';
  return 'eighths';
}

function createRhythmSlots(beatsPerBar: number, rhythm: ReturnType<typeof resolveRhythm>): RhythmSlot[] {
  const slots: RhythmSlot[] = [];
  const add = (beat: number, durationBeats: number, accent: boolean) => {
    if (beat >= beatsPerBar) return;
    slots.push({ beat, durationBeats, accent });
  };

  if (rhythm === 'eighths') {
    for (let step = 0; step < Math.ceil(beatsPerBar * 2); step++) {
      add(step * 0.5, 0.46, step % 2 === 0);
    }
  } else if (rhythm === 'shuffle') {
    for (let beat = 0; beat < beatsPerBar; beat++) {
      add(beat, 0.62, true);
      add(beat + 2 / 3, 0.29, false);
    }
  } else if (rhythm === 'triplets') {
    for (let beat = 0; beat < beatsPerBar; beat++) {
      add(beat, 0.29, true);
      add(beat + 1 / 3, 0.29, false);
      add(beat + 2 / 3, 0.29, false);
    }
  } else if (rhythm === 'dotted') {
    for (let beat = 0; beat < beatsPerBar; beat++) {
      add(beat, 0.68, true);
      add(beat + 0.75, 0.22, false);
    }
  } else if (rhythm === 'syncopated') {
    const beatScale = beatsPerBar / 4;
    [0, 0.75, 1.5, 2, 2.75, 3.5].forEach((position, index) => {
      add(position * beatScale, index % 2 === 0 ? 0.36 : 0.24, index === 0 || index === 3);
    });
  } else {
    const step = beatsPerBar >= 4 ? 2 : beatsPerBar / 2;
    for (let beat = 0; beat < beatsPerBar; beat += step) {
      add(beat, Math.min(1.7, step * 0.88), beat === 0);
    }
  }

  return slots;
}

function chooseGuitarPosition(note: string, previousMidi: number | null): { string: number; fret: number; midi: number } {
  const targetClass = pitchClass(note);
  let best: { string: number; fret: number; midi: number } | null = null;
  let bestCost = Number.POSITIVE_INFINITY;

  GUITAR_OPEN_MIDI.forEach((openMidi, string) => {
    for (let fret = 0; fret <= 18; fret++) {
      const midi = openMidi + fret;
      if (midi < 55 || midi > 81 || midi % 12 !== targetClass) continue;

      const motionCost = previousMidi === null ? Math.abs(midi - 67) * 0.35 : Math.abs(midi - previousMidi);
      const positionCost = Math.abs(fret - 7) * 0.08;
      const cost = motionCost + positionCost;
      if (cost < bestCost) {
        best = { string, fret, midi };
        bestCost = cost;
      }
    }
  });

  return best ?? { string: 2, fret: 0, midi: GUITAR_OPEN_MIDI[2] };
}

function pickChordTone(notes: string[], previousMidi: number | null, random: () => number): string {
  const tones = notes.map(normalizePitch).filter(note => pitchClass(note) >= 0);
  if (tones.length === 0) return 'C';

  const candidates = tones.map(note => ({
    note,
    distance: previousMidi === null
      ? Math.abs(chooseGuitarPosition(note, 67).midi - 67)
      : Math.abs(chooseGuitarPosition(note, previousMidi).midi - previousMidi),
  }));
  const weights = candidates.map(candidate => 1 / (1 + candidate.distance * 0.12));
  const totalWeight = weights.reduce((sum, weight) => sum + weight, 0);
  let choice = random() * totalWeight;

  for (let index = 0; index < candidates.length; index++) {
    choice -= weights[index];
    if (choice <= 0) return candidates[index].note;
  }

  return candidates[candidates.length - 1].note;
}

function durationName(durationBeats: number): string {
  if (durationBeats <= 0.3) return '16n';
  if (durationBeats <= 0.55) return '8n';
  if (durationBeats <= 0.8) return '8n.';
  if (durationBeats <= 1.2) return '4n';
  if (durationBeats <= 2.1) return '2n';
  return '1n';
}

export function generateMelodyEvents(
  arrangement: FretLabArrangement,
  scaleNotes: string[],
  rhythm: MelodyRhythm = 'style',
): GeneratedMelodyEvent[] {
  const beatsPerBar = Math.max(1, arrangement.timeSignature.beats);
  const scale = scaleNotes.map(normalizePitch).filter(note => pitchClass(note) >= 0);
  const safeScale = scale.length > 0 ? scale : [normalizePitch(arrangement.key) || 'C'];
  const random = seededRandom(arrangement.seed + 47);
  const style = getStyleRule(arrangement.genre);
  const resolvedRhythm = resolveRhythm(arrangement.genre, rhythm);
  const events: GeneratedMelodyEvent[] = [];
  let previousMidi: number | null = null;

  const getChordAt = (bar: number, beat = 0) => {
    const absoluteBeat = bar * beatsPerBar + beat;
    return arrangement.chords.find(chord =>
      chord.beatStart <= absoluteBeat &&
      chord.beatStart + chord.durationBeats > absoluteBeat,
    ) ?? arrangement.chords[Math.min(bar, Math.max(0, arrangement.chords.length - 1))];
  };

  const phraseLength = style.phraseLengthBars;
  for (let phraseStart = 0; phraseStart < arrangement.bars; phraseStart += phraseLength) {
    const phraseBars = Math.min(phraseLength, arrangement.bars - phraseStart);
    const contourChoices = STYLE_CONTOUR_INDICES[arrangement.genre];
    const contour = MELODIC_CONTOURS[contourChoices[Math.floor(random() * contourChoices.length)]];
    const answerContour = [...contour].reverse().map(step => -step);
    const contourRotation = Math.floor(random() * contour.length);
    const rhythmTemplates = STYLE_RHYTHM_TEMPLATES[arrangement.genre];
    const rhythmPatternRotation = rhythm === 'style'
      ? Math.floor(random() * rhythmTemplates.length)
      : 0;

    const questionBars = Math.max(1, Math.floor(phraseBars / 2));
    for (let barOffset = 0; barOffset < phraseBars; barOffset++) {
      const bar = phraseStart + barOffset;
      const barStart = bar * beatsPerBar;
      const isAnswer = barOffset >= questionBars;
      const isPhraseEnd = barOffset === phraseBars - 1;
      const barChord = getChordAt(bar);
      const chordTones = barChord?.notes?.length
        ? barChord.notes.map(normalizePitch).filter(note => pitchClass(note) >= 0)
        : [normalizePitch(arrangement.key) || 'C'];

      let slots: RhythmSlot[];
      if (rhythm === 'style') {
        const pattern = rhythmTemplates[(rhythmPatternRotation + barOffset) % rhythmTemplates.length];
        const beatScale = beatsPerBar / 4;
        slots = pattern.map(slot => ({
          ...slot,
          beat: slot.beat * beatScale,
          durationBeats: slot.durationBeats * beatScale,
        }));
      } else if (resolvedRhythm === 'shuffle') {
        slots = [
          { beat: 0, durationBeats: 0.7, accent: true },
          { beat: 0.75, durationBeats: 0.28, accent: false },
          { beat: 2, durationBeats: 0.7, accent: true },
          { beat: 3, durationBeats: 0.7, accent: true },
        ];
      } else if (resolvedRhythm === 'syncopated') {
        slots = [
          { beat: 0, durationBeats: 0.35, accent: true },
          { beat: 0.75, durationBeats: 0.25, accent: false },
          { beat: 1.5, durationBeats: 0.35, accent: false },
          { beat: 2, durationBeats: 0.35, accent: true },
          { beat: 2.75, durationBeats: 0.25, accent: false },
          { beat: 3.5, durationBeats: 0.35, accent: false },
        ];
      } else if (resolvedRhythm === 'triplets') {
        slots = [0, 1, 2, 3].flatMap(beat => [
          { beat, durationBeats: 0.28, accent: beat === 0 || beat === 2 },
          { beat: beat + 2 / 3, durationBeats: 0.28, accent: false },
        ]);
      } else if (rhythm === 'eighths') {
        slots = [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5].map((beat, index) => ({
          beat,
          durationBeats: 0.46,
          accent: index % 2 === 0,
        }));
      } else if (rhythm === 'dotted') {
        slots = [0, 0.75, 1, 1.75, 2, 2.75, 3, 3.75].map((beat, index) => ({
          beat,
          durationBeats: index % 2 === 0 ? 0.68 : 0.22,
          accent: index % 2 === 0,
        }));
      } else if (rhythm === 'long') {
        slots = [
          { beat: 0, durationBeats: 1.4, accent: true },
          { beat: 2, durationBeats: 1.2, accent: true },
        ];
      } else if (style.melodyDensity === 'high') {
        slots = [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5].map((beat, index) => ({
          beat,
          durationBeats: 0.42,
          accent: index % 4 === 0,
        }));
      } else if (style.melodyDensity === 'medium') {
        slots = [0, 1, 2, 2.75, 3.5].map((beat, index) => ({
          beat,
          durationBeats: index === 4 ? 0.4 : 0.72,
          accent: beat === 0 || beat === 2,
        }));
      } else {
        slots = [
          { beat: 0, durationBeats: 0.8, accent: true },
          { beat: 1.5, durationBeats: 0.65, accent: false },
          { beat: 3, durationBeats: 0.85, accent: true },
        ];
      }

      const minCount = style.melodyDensityPerBar.min;
      const maxCount = style.melodyDensityPerBar.max;
      slots = slots.slice(0, Math.max(minCount, Math.min(maxCount, slots.length)));
      const hasFollowingPhrase = phraseStart + phraseBars < arrangement.bars;
      const pauseBeats = isPhraseEnd && hasFollowingPhrase
        ? Math.min(style.pauseAfterPhraseBeats, beatsPerBar)
        : 0;
      const phraseEndBeat = beatsPerBar - pauseBeats;
      if (isPhraseEnd) {
        slots = slots.filter(slot => slot.beat < phraseEndBeat);
        const lastSlot = slots[slots.length - 1];
        const cadenceStart = Math.max(0, phraseEndBeat - Math.min(0.75, phraseEndBeat / 2));
        if (lastSlot && lastSlot.beat > cadenceStart) {
          lastSlot.beat = cadenceStart;
          lastSlot.durationBeats = phraseEndBeat - cadenceStart;
        }
      }

      slots.forEach((slot, slotIndex) => {
        const strongBeat = slot.beat === 0 || slot.beat === 2;
        const isCadence = isPhraseEnd && slotIndex === slots.length - 1;
        let note: string;

        if (strongBeat || isCadence) {
          const tones = chordTones.length > 0 ? chordTones : [safeScale[0]];
          note = isCadence ? tones[0] : pickChordTone(tones, previousMidi, random);
        } else {
          const contourIndex = (slotIndex + barOffset * 2 + contourRotation) % contour.length;
          const selectedContour = isAnswer ? answerContour : contour;
          const scaleOffset = selectedContour
            .slice(0, contourIndex + 1)
            .reduce((sum, step) => sum + step, 0);
          const anchorDegree = nearestScaleDegree(chordTones[0], safeScale);
          const noteIndex = (anchorDegree + scaleOffset % safeScale.length + safeScale.length) % safeScale.length;
          note = safeScale[noteIndex];
        }

        const previousBeforePosition = previousMidi;
        const position = chooseGuitarPosition(note, previousBeforePosition);
        previousMidi = position.midi;
        const durationBeats = Math.max(0.25, Math.min(
          slot.durationBeats,
          (isPhraseEnd ? phraseEndBeat : beatsPerBar) - slot.beat,
        ));

        let articulation: GeneratedMelodyEvent['articulation'] = 'none';
        if (isCadence && style.vibratoOnPhraseEnd) {
          articulation = 'vibrato';
        } else if (style.bendUsage === 'frequent' && slot.beat >= 1.5 && random() < 0.18) {
          articulation = 'bend';
        } else if (!strongBeat && previousBeforePosition !== null && Math.abs(position.midi - previousBeforePosition) >= 2 &&
          (arrangement.genre === 'Rock' || arrangement.genre === 'Hard Rock' ||
           arrangement.genre === 'Blues Rock' || arrangement.genre === 'Blues') &&
          random() < 0.12) {
          articulation = 'slide';
        } else if ((arrangement.genre === 'Metal' || arrangement.genre === 'Thrash Metal') &&
          durationBeats <= 0.5 && random() < 0.22) {
          articulation = random() < 0.5 ? 'hammer' : 'pull';
        }

        events.push({
          track: 'melody',
          pitch: normalizePitch(note) || safeScale[0],
          string: position.string,
          fret: position.fret,
          isRest: false,
          beatStart: barStart + slot.beat,
          durationBeats,
          velocity: isCadence ? 0.94 : slot.accent ? 0.82 : 0.62,
          articulation,
          accent: slot.accent || isCadence,
          duration: durationName(durationBeats),
        });
      });

      if (isPhraseEnd && hasFollowingPhrase) {
        events.push({
          track: 'melody',
          pitch: safeScale[0],
          string: 2,
          fret: null,
          isRest: true,
          beatStart: barStart + phraseEndBeat,
          durationBeats: pauseBeats,
          velocity: 0,
          articulation: 'none',
          accent: false,
          duration: durationName(pauseBeats),
        });
      }
    }
  }

  return events;
}

export function generateBassEvents(arrangement: FretLabArrangement): BassBeatEvent[] {
  const random = seededRandom(arrangement.seed + 17);
  const rule = getStyleRule(arrangement.genre);
  const events: BassBeatEvent[] = [];
  const beatsPerBar = Math.max(1, arrangement.timeSignature.beats);
  const beatScale = beatsPerBar / 4;
  const patterns: Record<StyleRule['bassPattern'], BassPatternSlot[][]> = {
    'root-fifth': [
      [{ beat: 0, tone: 0, duration: 1 }, { beat: 2, tone: 2, duration: 1 }],
      [{ beat: 0, tone: 0, duration: 0.8 }, { beat: 1, tone: 2, duration: 0.8 }, { beat: 2, tone: 0, duration: 0.8 }, { beat: 3, tone: 2, duration: 0.8 }],
      [{ beat: 0, tone: 0, duration: 0.8 }, { beat: 1.5, tone: 2, duration: 0.45 }, { beat: 2, tone: 0, duration: 0.8 }, { beat: 3.25, tone: 1, duration: 0.45 }],
    ],
    eighths: [
      Array.from({ length: 8 }, (_, index) => ({ beat: index * 0.5, tone: (index % 2 === 0 ? 0 : 2) as 0 | 2, duration: 0.42 })),
      Array.from({ length: 8 }, (_, index) => ({ beat: index * 0.5, tone: ([0, 2, 1, 2][index % 4]) as 0 | 1 | 2, duration: 0.42 })),
    ],
    walking: [
      [0, 1, 2, 1].map((tone, beat) => ({ beat, tone: tone as 0 | 1 | 2, duration: 0.88 })),
      [0, 2, 1, 2].map((tone, beat) => ({ beat, tone: tone as 0 | 1 | 2, duration: 0.88 })),
    ],
    syncopated: [
      [{ beat: 0, tone: 0, duration: 0.55 }, { beat: 0.75, tone: 2, duration: 0.35 }, { beat: 1.5, tone: 1, duration: 0.4 }, { beat: 2, tone: 0, duration: 0.55 }, { beat: 2.75, tone: 2, duration: 0.35 }, { beat: 3.5, tone: 1, duration: 0.35 }],
      [{ beat: 0, tone: 0, duration: 0.65 }, { beat: 1.25, tone: 1, duration: 0.35 }, { beat: 2, tone: 2, duration: 0.55 }, { beat: 3, tone: 0, duration: 0.4 }, { beat: 3.5, tone: 2, duration: 0.35 }],
    ],
    pedal: [
      [0, 1, 2, 3].map(beat => ({ beat, tone: 0 as const, duration: 0.82 })),
      [0, 1, 2, 3].map((beat, index) => ({ beat, tone: (index === 2 ? 2 : 0) as 0 | 2, duration: 0.82 })),
    ],
    gallop: [
      [{ beat: 0, tone: 0, duration: 0.62 }, { beat: 0.75, tone: 0, duration: 0.2 }, { beat: 1, tone: 0, duration: 0.2 }, { beat: 2, tone: 2, duration: 0.62 }, { beat: 2.75, tone: 0, duration: 0.2 }, { beat: 3, tone: 0, duration: 0.2 }],
      [{ beat: 0, tone: 0, duration: 0.62 }, { beat: 0.75, tone: 0, duration: 0.2 }, { beat: 1, tone: 2, duration: 0.2 }, { beat: 2, tone: 0, duration: 0.62 }, { beat: 2.75, tone: 0, duration: 0.2 }, { beat: 3, tone: 2, duration: 0.2 }],
    ],
  };

  arrangement.chords.forEach(chord => {
    if (chord.locked) return;
    const chordTones = chord.notes.length > 0
      ? chord.notes.slice(0, 3).map(normalizePitch)
      : [normalizePitch(chord.chord.match(/^[A-G](?:#|b)?/i)?.[0] ?? arrangement.key)];
    const tones = [chordTones[0], chordTones[1] ?? chordTones[0], chordTones[2] ?? chordTones[0]];
    const barStart = chord.beatStart;
    const pattern = patterns[rule.bassPattern][Math.floor(random() * patterns[rule.bassPattern].length)];
    const slots = pattern.filter(slot => slot.beat * beatScale < chord.durationBeats);

    slots.forEach((slot, index) => {
      const beatOffset = slot.beat * beatScale;
      const nextBeatOffset = (slots[index + 1]?.beat ?? 4) * beatScale;
      const availableDuration = Math.max(0.125, Math.min(chord.durationBeats - beatOffset, nextBeatOffset - beatOffset));
      const durationBeats = Math.min(slot.duration * beatScale, availableDuration * 0.9);
      const technique: BassBeatEvent['technique'] = slot.tone === 0
        ? rule.bassPattern === 'pedal' ? 'pedal' : 'root'
        : slot.tone === 2 ? 'fifth' : rule.bassPattern === 'walking' ? 'walking' : 'passing';

      events.push({
        track: 'bass',
        pitch: `${tones[slot.tone] || arrangement.key}1`,
        beatStart: barStart + beatOffset,
        durationBeats,
        velocity: (index === 0 ? 0.86 : 0.68) + random() * 0.14,
        technique,
      });
    });
  });

  return events;
}

export function generateDrumEvents(arrangement: FretLabArrangement): DrumBeatEvent[] {
  const random = seededRandom(arrangement.seed + 31);
  const rule = getStyleRule(arrangement.genre);
  const events: DrumBeatEvent[] = [];
  const beatsPerBar = Math.max(1, arrangement.timeSignature.beats);
  const beatScale = beatsPerBar / 4;
  const eighths = Array.from({ length: 8 }, (_, index) => index * 0.5);
  const shuffleRide = Array.from({ length: 4 }, (_, beat) => [beat, beat + 2 / 3]).flat();
  const grooves: Record<StyleRule['drumPattern'], DrumGroove[]> = {
    rock: [
      { kick: [0, 2], snare: [1, 3], hats: eighths },
      { kick: [0, 1.5, 2], snare: [1, 3], hats: eighths },
      { kick: [0, 2, 3.5], snare: [1, 3], hats: [0, 0.5, 1, 1.5, 2, 2.5, 3] },
    ],
    'hard-rock': [
      { kick: [0, 1.5, 2, 3.5], snare: [1, 3], hats: eighths },
      { kick: [0, 2, 2.5], snare: [1, 3], hats: eighths },
      { kick: [0, 1, 2, 3], snare: [1, 3], hats: [0, 0.5, 1, 1.5, 2, 2.5, 3] },
    ],
    metal: [
      { kick: eighths, snare: [1, 3], hats: eighths },
      { kick: [0, 0.5, 1.5, 2, 2.5, 3.5], snare: [1, 3], hats: eighths },
      { kick: [0, 1, 1.5, 2, 3, 3.5], snare: [1, 3], hats: [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5] },
    ],
    thrash: [
      { kick: eighths, snare: [1, 3], hats: eighths },
      { kick: [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5], snare: [1, 2.5], hats: eighths },
      { kick: [0, 0.5, 1.5, 2, 2.5, 3, 3.5], snare: [1, 3], hats: [0, 0.5, 1, 1.5, 2, 2.5, 3] },
    ],
    groove: [
      { kick: [0, 1.5, 2.5, 3.5], snare: [1, 3], ghostSnare: [0.5, 2.5], hats: eighths },
      { kick: [0, 1, 2.5, 3], snare: [1, 3], ghostSnare: [0.75, 2.75], hats: [0, 0.5, 1, 1.5, 2, 2.5, 3] },
      { kick: [0, 1.5, 2, 3.25], snare: [1, 3], ghostSnare: [0.5, 2.75], hats: eighths },
    ],
    blues: [
      { kick: [0, 2], snare: [1, 3], hats: [], ride: shuffleRide },
      { kick: [0, 1.5, 2], snare: [1, 3], hats: [], ride: shuffleRide },
      { kick: [0, 2, 3], snare: [1, 3], hats: [], ride: [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5] },
    ],
    funk: [
      { kick: [0, 0.75, 1.5, 2, 2.75, 3.5], snare: [1, 3], ghostSnare: [0.5, 2.5], hats: eighths },
      { kick: [0, 1.5, 2.5, 3.25], snare: [1, 3], ghostSnare: [0.75, 2.5], hats: [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5] },
      { kick: [0, 0.5, 1.75, 2.5, 3], snare: [1, 3], ghostSnare: [0.5, 2.75], hats: eighths },
    ],
  };

  for (let bar = 0; bar < arrangement.bars; bar++) {
    const barStart = bar * beatsPerBar;
    const grooveBank = grooves[rule.drumPattern];
    const groove = grooveBank[Math.floor(random() * grooveBank.length)];
    const drumDuration = 0.22 * beatScale;
    const append = (hit: DrumBeatEvent['hit'], offset: number, velocity: number, ghost = false) => {
      const scaledOffset = offset * beatScale;
      if (scaledOffset >= beatsPerBar) return;
      events.push({
        track: 'drums',
        hit,
        beatStart: barStart + scaledOffset,
        durationBeats: Math.min(drumDuration, beatsPerBar - scaledOffset),
        velocity,
        ...(ghost ? { ghost: true } : {}),
      });
    };

    groove.kick.forEach(offset => {
      if (offset === 0 || random() > 0.1) append('kick', offset, 0.78 + random() * 0.2);
    });
    groove.snare.forEach(offset => append('snare', offset, 0.82 + random() * 0.16));
    groove.ghostSnare?.forEach(offset => {
      if (random() > 0.25) append('snare', offset, 0.28 + random() * 0.18, true);
    });
    groove.hats.forEach(offset => {
      if (offset === 0 || random() > 0.12) append('hihat', offset, 0.38 + random() * 0.28);
    });
    groove.ride?.forEach(offset => {
      if (offset === 0 || random() > 0.08) append('ride', offset, 0.44 + random() * 0.3);
    });

    if ((bar === 0 || bar % 2 === 0) && random() > 0.25) {
      append('crash', 0, 0.72 + random() * 0.24);
    }

    if ((bar + 1) % 4 === 0 || bar === arrangement.bars - 1) {
      const fill = random() < 0.5 ? [2.5, 3, 3.5] : [2, 2.75, 3.25, 3.5];
      fill.forEach((offset, index) => {
        append(index % 2 === 0 ? 'tom' : 'snare', offset, 0.58 + random() * 0.3);
      });
      append('crash', 3.75, 0.78 + random() * 0.2);
    }
  }

  return events;
}

export function getGenreNames(): FretLabGenre[] {
  return ['Rock', 'Hard Rock', 'Metal', 'Thrash Metal', 'Groove Metal', 'Blues', 'Blues Rock', 'Funk'];
}
