import MidiWriter from 'midi-writer-js';

const TICKS_PER_QUARTER = 128;

export interface MidiExportNote {
  isRest?: boolean;
  fret: number | null;
  string: number;
  beatStart: number;
  beatDuration?: number;
  duration?: string;
  velocity?: number;
}

export interface MidiExportChord {
  name: string;
  notes: string[];
  beatStart: number;
  durationBeats: number;
}

export interface MidiExportData {
  bars: number;
  totalBeats: number;
  chords: MidiExportChord[];
  notes: MidiExportNote[];
}

export function exportSoloToMidi(
  soloData: MidiExportData,
  _keyNote: string,
  _bpm: number,
): Uint8Array {
  const track = new MidiWriter.Track();
  track.addEvent(new (MidiWriter as any).ProgramChangeEvent({ instrument: 29 }));

  soloData.notes.forEach(note => {
    if (note.isRest || note.fret === null) return;
    const stringOpen = [64, 59, 55, 50, 45, 40];
    const pitch = stringOpen[note.string] + note.fret;
    const durationMap: Record<string, string> = {
      '1n': '1',
      '2n': '2',
      '4n': '4',
      '8n': '8',
      '16n': '16',
      '4n.': '4.',
      '8n.': '8.',
    };

    const beatDuration = note.beatDuration;
    const midiDuration = beatDuration !== undefined && Number.isFinite(beatDuration) && beatDuration > 0
      ? `T${Math.max(1, Math.round(beatDuration * TICKS_PER_QUARTER))}`
      : note.duration
        ? durationMap[note.duration] || '8'
        : '8';

    track.addEvent(new MidiWriter.NoteEvent({
      pitch: [String(pitch)],
      duration: midiDuration,
      startTick: Math.round(note.beatStart * TICKS_PER_QUARTER),
      velocity: Math.round((note.velocity || 0.7) * 127),
    }));
  });

  return new MidiWriter.Writer(track).buildFile() as Uint8Array;
}

export function exportChordsToMidi(
  soloData: MidiExportData,
  _bpm: number,
): Uint8Array {
  const track = new MidiWriter.Track();
  track.addEvent(new (MidiWriter as any).ProgramChangeEvent({ instrument: 1 }));
  const noteNames = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

  soloData.chords.forEach(chord => {
    const pitches = chord.notes
      .map(note => noteNames.indexOf(note.replace(/[0-9]/g, '')))
      .filter(index => index >= 0)
      .map(index => String(index + 60));

    if (pitches.length) {
      track.addEvent(new MidiWriter.NoteEvent({
        pitch: pitches,
        duration: '1',
        startTick: Math.round(chord.beatStart * TICKS_PER_QUARTER),
        velocity: 80,
      }));
    }
  });

  return new MidiWriter.Writer(track).buildFile() as Uint8Array;
}

export interface MidiBassEvent {
  pitch: string;
  beatStart: number;
  durationBeats: number;
  velocity?: number;
}

export interface MidiDrumEvent {
  hit: 'kick' | 'snare' | 'hihat' | 'crash' | 'ride' | 'tom';
  beatStart: number;
  velocity?: number;
}

export function exportBassToMidi(events: MidiBassEvent[], _bpm: number): Uint8Array {
  const track = new MidiWriter.Track();
  track.addEvent(new (MidiWriter as any).ProgramChangeEvent({ instrument: 33 }));

  events.forEach(event => {
    track.addEvent(new MidiWriter.NoteEvent({
      pitch: [event.pitch],
      duration: '8',
      startTick: Math.round(event.beatStart * TICKS_PER_QUARTER),
      velocity: Math.round((event.velocity ?? 0.8) * 127),
    }));
  });

  return new MidiWriter.Writer(track).buildFile() as Uint8Array;
}

const drumMidiNotes: Record<MidiDrumEvent['hit'], string> = {
  kick: '36',
  snare: '38',
  hihat: '42',
  crash: '49',
  ride: '51',
  tom: '45',
};

export function exportDrumsToMidi(events: MidiDrumEvent[], _bpm: number): Uint8Array {
  const track = new MidiWriter.Track();
  track.addEvent(new (MidiWriter as any).TrackNameEvent({ text: 'Drums' }));

  events.forEach(event => {
    track.addEvent(new MidiWriter.NoteEvent({
      pitch: [drumMidiNotes[event.hit]],
      duration: '16',
      startTick: Math.round(event.beatStart * TICKS_PER_QUARTER),
      velocity: Math.round((event.velocity ?? 0.8) * 127),
    }));
  });

  return new MidiWriter.Writer(track).buildFile() as Uint8Array;
}

export function downloadMidiFile(bytes: Uint8Array, filename: string): void {
  const blob = new Blob([bytes as unknown as BlobPart], { type: 'audio/midi' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = `${filename}.mid`;
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  URL.revokeObjectURL(url);
}
